//! Ripple, insert time, range delete, lift, close gap and freeze frame —
//! spec §6 rows `ripple_delete`, `ripple_delete_range`,
//! `ripple_delete_ranges`, `lift_range`, `close_gap`, `insert_time` and
//! `freeze_frame`, and the §11 decisions they implement.
//!
//! What separates these from `edit_clip.rs`'s ops is that they move
//! material they were never given: closing or opening a hole in the cut
//! shifts clips the caller did not name, on tracks the caller did not name.
//! Three rules run through all of it (spec §11):
//!
//! 1. **Ripple is timeline-wide.** A ripple shifts every UNLOCKED track,
//!    not only the tracks the removed clips were on — that is the one
//!    behaviour that keeps a music bed in sync with the
//!    picture it was cut to.
//! 2. **Locked tracks never move.** Locking a track is how the user says
//!    "this stays where it is", and it is the only protection from a
//!    timeline-wide shift.
//! 3. **Straddling clips stay put.** A clip that covers a boundary is not
//!    cut by a shift; only clips that begin at or after the boundary move.
//!    Clips never push each other, and a shift never splits anything the
//!    user did not ask to split.
//!
//! Everything here is composed from the primitives in `edit_clip.rs` —
//! `split_clips`, `split_under_playhead`, `snapped`, `finish` — rather than
//! restating them, so a split made by a range delete is the same split ⌘T
//! makes.

use crate::cursor_props::with_base_cursor;
use crate::edit_clip::clip_end;
use crate::model::{Clip, Enabled, Project, Source, VideoProps};
use crate::outcome::Outcome;
use crate::source_window::source_read_by;
use crate::time::{Ticks, TIMESCALE};

/// Default freeze length (spec §6). Two seconds is long enough for a hold
/// to read as deliberate and short enough that the user trims it rather
/// than deletes it.
const DEFAULT_FREEZE_DURATION: Ticks = 2 * TIMESCALE;

/// A half-open span of project time a ripple removes.
#[derive(Debug, Clone, Copy)]
struct Span {
    start: Ticks,
    end: Ticks,
}

/// The spans merged into disjoint ones, ascending.
///
/// Adjacent spans merge as well as overlapping ones: two clips that meet at
/// a cut leave ONE hole, and shifting twice by two lengths is the same as
/// shifting once by their sum only when the boundaries are handled in one
/// piece. Empty spans are dropped — a zero-length hole moves nothing.
fn union(mut spans: Vec<Span>) -> Vec<Span> {
    spans.sort_by_key(|s| (s.start, s.end));
    let mut out: Vec<Span> = Vec::new();
    for span in spans {
        if span.end <= span.start {
            continue;
        }
        match out.last_mut() {
    /// the clips a later span's bounds were computed against.
    ///
    /// The named clips are removed whether or not their track is locked —
    /// the caller named them — while the lock decides only what may SHIFT.
    /// Each one's linked partner on an unlocked track goes too (AU-91).
    ///
    /// Markers do not move. A ripple can remove several spans, and a marker
    /// inside one of them has no moment left to name and nowhere to go that
    /// is not already taken by another marker; leaving every mark in place
    /// is visible and fixable, where a silent drop is not. (`insert_time`
    /// is the opposite case — one point, one length, no collision possible
    /// — and does move them.)
    ///
    /// `Err` on an unknown clip id; an identity for an empty selection.
    pub fn ripple_delete(&self, clips: &[u32]) -> Result<Outcome, String> {
        let selection = self.selected_clips(&self.with_links(clips)?)?;
        if selection.is_empty() {
            return Ok(Outcome::Identity);
        }
        let ids: Vec<u32> = selection.iter().map(|c| c.id).collect();
        let spans = union(
            selection
                .iter()
                .map(|c| Span {
                    start: c.start,
                    end: clip_end(c),
                })
                .collect(),
        );

        let mut next = self.clone();
        next.clips.retain(|c| !ids.contains(&c.id));
        for span in spans.iter().rev() {
            let length = span.end.saturating_sub(span.start);
            if let Some(why) = shift_clips(&mut next, span.end, -length) {
                return Ok(Outcome::Refused(why));
            }
        }
        // A shift can slide a clip onto a straddling neighbour on another
        // track; an overlap IS a transition, so give the newcomer the
        // default rather than leaving two stacked layers.
        let unlocked = unlocked_tracks(&next);
        self.finish_placement(next, &unlocked)
    }

    /// Removes everything between `from` and `to` on unlocked tracks and
    /// closes the hole — the range form of ripple delete (spec §6).
    ///
    /// Both bounds are cut first (`split_under_playhead` IS "split every
    /// unlocked clip here"), so afterwards every unlocked clip that touched
    /// the range lies entirely inside it; those are removed, and everything
    /// starting at or after `to` shifts left by the range's length.
    ///
    /// Clips on LOCKED tracks are neither split nor removed, even when they
    /// lie inside the range: rule 2 is absolute, and a locked track keeps
    /// exactly what it had.
    ///
    /// The bounds are snapped, clamped to 0 and ordered, so a drag that
    /// ended left of where it began is the same range. An empty range is an
    /// identity.
    ///
    /// It is [`Project::ripple_delete_ranges`] with one pair, and nothing
    /// else: with a single span there is nothing for the merge to merge and
    /// nothing for the right-to-left loop to order, so the two are
    /// step-for-step the same edit. Keeping a second body here would be a
    /// second implementation of one algorithm, free to drift.
    pub fn ripple_delete_range(&self, from: Ticks, to: Ticks) -> Result<Outcome, String> {
        self.ripple_delete_ranges(&[[from, to]])
    }

    /// Removes SEVERAL ranges and closes each hole in one edit — the
    /// silence cut (spec §6), one op because it is one undo step.
    ///
    /// **The op is defined as merge-then-cut, not as N
    /// `ripple_delete_range`s**, and the difference is visible in the
    /// document, so it is worth stating plainly: each pair is snapped,
    /// clamped to 0 and put in order exactly as the single range is, the
    /// results are MERGED — touching pairs as well as overlapping ones —
    /// and only the survivors are cut. Two quiet spans that meet leave one
    /// hole, and cutting at a boundary that no longer exists would split
    /// clips into fragments nobody asked for and burn the ids to prove it.
    /// A caller that wants N separate edits sends N ops.
    ///
    /// The survivors are cut and closed RIGHT TO LEFT, because closing an
    /// earlier hole moves the clips a later hole's bounds were measured
    /// against — every bound here is a time in the project as the caller
    /// saw it, not in the project as the previous cut left it.
    ///
    /// `set_gained_transitions` runs ONCE at the end, over the unlocked
    /// tracks, as it does for `ripple_delete`'s own union of spans: a clip
    /// that overlaps a neighbour between two shifts and then slides clear
    /// again should not come out holding a transition for an overlap that
    /// no longer exists.
    ///
    /// Everything else is `ripple_delete_range`'s contract: locked tracks
    /// are neither split, removed nor shifted; straddlers stay put; markers
    /// do not move (a marker inside a removed span has no moment left to
    /// name, and giving the plural a second marker rule would give two
    /// ripples two rules); a clip a shift brings onto a neighbour gains the
    /// default transition rather than stacking.
    ///
    /// There is no cap on the list: the op is pure, so nothing is
    /// half-applied, and a pathological call is already answered — each cut
    /// splits, every split validates, and `format::check_caps` refuses the
    /// clip count it would take to get there.
    ///
    /// An empty list, a list of empty ranges, and a list that merges to
    /// nothing all change nothing.
    pub fn ripple_delete_ranges(&self, ranges: &[[Ticks; 2]]) -> Result<Outcome, String> {
        // Snapped FIRST, merged after: two ranges three ticks apart are the
        // same range once both bounds are on the frame grid, and only a
        // merge that runs afterwards can see it.
        let spans = union(
            ranges
                .iter()
                .filter_map(|pair| ordered_range(self, pair[0], pair[1]))
                .map(|(start, end)| Span { start, end })
                .collect(),
        );
        if spans.is_empty() {
            return Ok(Outcome::Identity);
        }

        let mut next = self.clone();
        for span in spans.iter().rev() {
            next = clear_range(&next, span.start, span.end)?;
            // Negated by subtraction rather than by `-length`, so an absurd
            // range cannot overflow on the negation.
            if let Some(why) = shift_clips(&mut next, span.end, span.start.saturating_sub(span.end))
            {
                return Ok(Outcome::Refused(why));
            }
        }
        let unlocked = unlocked_tracks(&next);
        self.finish_placement(next, &unlocked)
    }

    /// Removes everything between `from` and `to` on unlocked tracks and
    /// leaves the hole open — `ripple_delete_range` without the close
    /// (spec §6).
    ///
    /// The lift is the cut that costs nothing downstream: every clip that
    /// starts at or after `to` keeps the moment it had, so a mix, a caption
    /// track and a music bed stay where they were cut to. It is the
    /// counterpart of a ripple, not a lesser one — ⌫ with a range and
    /// nothing selected, where ⌘⌫ ripples.
    ///
    /// Markers do not move either, for the plainer reason that nothing
    /// under them did.
    ///
    /// The bounds are snapped, clamped to 0 and ordered, so a drag that
    /// ended left of where it began is the same range. An empty range, or
    /// one that held nothing an unlocked track could give up, is an identity.
    pub fn lift_range(&self, from: Ticks, to: Ticks) -> Result<Outcome, String> {
        let Some((start, end)) = ordered_range(self, from, to) else {
            return Ok(Outcome::Identity);
        };
        // No shift, so nothing can be brought into contact with anything
        // and no transition can be gained.
        self.finish(clear_range(self, start, end)?)
    }

    /// Closes the empty span on `track` that contains `at`: everything from
    /// the far side of it, on every unlocked track, moves left by the gap's
    /// length (spec §6).
    ///
    /// The gap is bounded by the nearest clip edges ON `track` — the last
    /// end at or before `at`, or 0 when nothing precedes it, and the first
    /// start after it. A playhead ON a clip is not in a gap, and a gap with
    /// nothing after it is not one to close: both refuse, naming the clip or
    /// the track (spec §11 #88).
    ///
    /// The shift is the ripple's, timeline-wide over unlocked tracks with
    /// straddlers staying put, so the material that follows the gap keeps
    /// its relative timing on every track. **A locked `track` refuses in
    /// [`locked_track`]'s words**: its own clips are the ones that would not
    /// move, and closing a gap by shifting everything except the track the
    /// gap is on is not what anyone asked for.
    ///
    /// **Refuses when the shift would break the overlap rule** anywhere it
    /// moved something, rather than closing as far as it can. A gap closes
    /// fully or not at all: a partial close leaves the user looking at a
    /// smaller gap with no way to tell whether the op ran.
    ///
    /// Markers do not move, as they do not for any other ripple (only
    /// `insert_time`, where no collision is possible, moves them).
    ///
    /// `Err` for an unknown track.
    pub fn close_gap(&self, track: u32, at: Ticks) -> Result<Outcome, String> {
        if self.require_track(track)?.locked {
            return Ok(Outcome::Refused(locked_track(
                track,
                "the gap on it cannot be closed",
            )));
        }
        let at = self.snapped(at).max(0);
        let ordered = self.clips_on_track(track);
        if let Some(on) = ordered.iter().find(|c| c.start <= at && at < clip_end(c)) {
            return Ok(Outcome::Refused(format!(
                "clip {} runs from {} to {} on track {track}, so {at} is not in a gap",
                on.id,
                on.start,
                clip_end(on)
            )));
        }
        let start = ordered
            .iter()
            .map(|c| clip_end(c))
            .filter(|end| *end <= at)
            .max()
            .unwrap_or(0);
        let Some(end) = ordered.iter().map(|c| c.start).filter(|s| *s > at).min() else {
            return Ok(Outcome::Refused(format!(
                "no clip on track {track} starts after {at}, so there is no gap to close"
            )));
        };
        if end <= start {
            return Ok(Outcome::Identity);
        }

        // Only the tracks something actually moves on can gain an overlap,
        // and only those are checked: a rule violation elsewhere is not
        // this op's to report, and refusing over one would make a gap
        // uncloseable for a reason the user cannot see.
        let mut touched: Vec<u32> = Vec::new();
        for clip in shifted(self, end).iter().filter_map(|id| self.clip(*id)) {
            if !touched.contains(&clip.track) {
                touched.push(clip.track);
            }
        }

        let mut next = self.clone();
        if let Some(why) = shift_clips(&mut next, end, start.saturating_sub(end)) {
            return Ok(Outcome::Refused(why));
        }
        for id in &touched {
            if let Err(why) = next.check_overlap_rule(&[], *id, &[]) {
                return Ok(Outcome::Refused(why));
            }
        }
        self.finish_placement(next, &touched)
    }

    /// Opens `length` of empty time at `at`: every clip on an unlocked
    /// track that starts at or after `at` shifts right, and straddling
    /// clips stay put (spec §6).
    ///
    /// Markers at or after `at` shift too. A marker names a moment in the
    /// CUT — "the intro ends here" — not a wall-clock time, so material
    /// inserted before it must carry it along; a marker left behind would
    /// point at whatever the insert pushed under it. No marker can collide:
    /// every mark at or after `at` moves by the same length, and the ones
    /// before it never reach `at`.
    ///
    /// `Err` for a length still negative after snapping; an identity for zero.
    pub fn insert_time(&self, at: Ticks, length: Ticks) -> Result<Outcome, String> {
        let at = self.snapped(at).max(0);
        let length = self.snapped(length);
        if length < 0 {
            return Err(format!("insert length must not be negative, not {length}"));
        }
        if length == 0 {
            return Ok(Outcome::Identity);
        }

        let mut next = self.clone();
        // A positive shift has no floor to refuse.
        let _ = shift_clips(&mut next, at, length);
        for marker in next.markers.iter_mut() {
            if marker.time >= at {
                marker.time = marker.time.saturating_add(length);
            }
        }
        self.finish(next)
    }

    /// Holds the frame under `at` for `duration` (default two seconds),
    /// spec §6.
    ///
    /// The three-op composition IS the definition: **split** the clip at
    /// `at`, **insert time** so `duration` of empty timeline opens across
    /// every unlocked track — which is what keeps the rest of the cut in
    /// sync with the hold (spec §11) — and then fill the hole this clip's
    /// track now has with a `still` naming the source time that was under
    /// the playhead. No image is extracted: a still is one source frame
    /// scaled in the composition (spec §11).
    ///
    /// The source time is `in + (at - start) × speed`, clamped inside the
    /// media so the still names a frame that exists. The still carries the
    /// clip's video properties EVALUATED at the cut, not its base ones: the
    /// frozen frame must sit exactly where the frame it froze sat, and an
    /// action may have been moving it. For the same reason the still gets
    /// no actions — the state it froze at is baked into its base props, and
    /// a copied action would animate away from the frame the cut matched.
    ///
    /// `Err` for an unknown clip, a non-media source, an `at` outside the
    /// clip, or a duration under one frame; refused, in the rule's own
    /// sentence, if the still would break the overlap rule.
    pub fn freeze_frame(
        &self,
        clip: u32,
        at: Ticks,
        duration: Option<Ticks>,
    ) -> Result<Outcome, String> {
        let target = self.require_clip(clip)?.clone();
        let Source::Media { media, r#in, .. } = target.source else {
            return Err(format!("clip {clip} is not a media clip"));
        };
        // A clip with no video props draws nothing, so there is no frame to
        // hold — the same "presence of the group is the aspect" rule the
        // property patches use.
        if target.video.is_none() {
            return Err(format!("clip {clip} has no video properties"));
        }

        let at = self.snapped(at);
        if at < target.start || at > clip_end(&target) {
            return Err(format!("clip {clip} does not cover {at}"));
        }
        let frame = self.frame();
        let duration = match duration {
            None => DEFAULT_FREEZE_DURATION,
            Some(given) => {
                let snapped = self.snapped(given);
                if snapped < frame {
                    return Err(format!(
                        "freeze duration must be at least one frame ({frame} ticks), not {given}"
                    ));
                }
                snapped
            }
        };

        let clip_t = at.saturating_sub(target.start);
        // The source the clip has read by the cut: through its map on a
        // ramped clip, the tick a split's two halves meet at (spec §11
        // SR-18 (f)).
        let source_at = r#in.saturating_add(source_read_by(&target, clip_t)).max(0);
        // The clamp only has to keep the still's source time inside the
        // media, which is `source_window.rs`'s `last_still_time`; a media
        // the project does not have cannot bound anything.
        let limit = self
            .media(media)
            .map_or(source_at, |m| self.last_still_time(m));
        let source_at = source_at.clamp(0, limit);

        let video = with_base_cursor(
            self.evaluate_clip(&target, clip_t).video,
            target.video.as_ref(),
        );
        let mut next = match self.split_clips(&[clip], at)? {
            Outcome::Applied(split) => split,
            // The playhead sat on a clip boundary: nothing to cut, and the
            // freeze still has somewhere to go.
            Outcome::Identity => self.clone(),
            Outcome::Refused(why) => return Ok(Outcome::Refused(why)),
        };
        match next.insert_time(at, duration)? {
            Outcome::Applied(inserted) => next = inserted,
            Outcome::Identity => {}
            Outcome::Refused(why) => return Ok(Outcome::Refused(why)),
        }

        let still = Clip {
            // A held frame has no sound, so the audio side is off and there
            // are no audio props to carry.
            enabled: Enabled {
                video: true,
                audio: false,
            },
            // A still is a NEW clip with new ends, so it does not inherit
            // the preset anchored to the ones it was taken from (format
            // version 8): a freeze taken mid-arrival would otherwise arrive
            // again, and one taken anywhere at all would carry a departure
            // onto a frame that is meant to hold. The evaluated placement
            // it keeps is the un-moved one — `evaluate_clip` never applies
            // motion — so the still sits exactly where the inspector said
            // the clip was, which is the documented jump (road map 5 §5h).
            video: Some(VideoProps {
                motion: None,
                ..video
            }),
            ..Clip::placed(
                next.allocate_id(),
                target.track,
                at,
                duration,
                Source::Still {
                    media,
                    at: source_at,
                },
            )
        };
        if let Err(why) = next.check_overlap_rule(std::slice::from_ref(&still), still.track, &[]) {
            return Ok(Outcome::Refused(why));
        }
        next.clips.push(still);
        self.finish(next)
    }
}

/// Cuts `clip_id` in two at project time `at`, in place. Returns false —
/// and changes nothing — when `at` is not strictly inside the clip, which
/// is the spec's refusal.
///
/// The second clip's BASE props are the evaluated state at the cut, so the
/// join is invisible; its actions are the ones that had not finished,
/// rebased to its own clip time. A graphic's `props` are the evaluated
/// ones, and a straddled action's first half ends at them (G-34).
pub(crate) fn split_clip(project: &mut Project, clip_id: u32, at: Ticks) -> bool {
    let Some(original) = project.clip(clip_id).cloned() else {
        return false;
    };
    let clip_t = at.saturating_sub(original.start);
    if clip_t <= 0 || clip_t >= original.duration {
        return false;
    }
    let state = project.evaluate_clip(&original, clip_t);
    let patch_source = state_patch(&state);
    // The ORIGINAL's map, read once: a ramped clip's halves meet at the
    // source it read by the cut (spec §11 SR-18 (e)). `None` for a
    // constant clip, which takes the one-rate path unchanged.
    let map = SpeedMap::of(&original);
    // Measured on the ORIGINAL, so a null `length` is `in` plus the WHOLE
    // duration, not the half either piece keeps.
    let pinned = effective_length(&original);

    let mut second = original.clone();
    second.id = project.allocate_id();
    second.start = at;
    second.duration = clip_end(&original).saturating_sub(at);
    // The cut consumes `clip_t` of timeline, which is `clip_t * speed` of
    // source — round(S(cut)) on a ramped clip, whose second half starts at
    // the rate in force there; a still's frozen frame and the sourceless
    // kinds do not move, which is `source_advanced_through`'s own rule.
    second.source = source_advanced_through(&original, clip_t);
    if let Some(map) = &map {
        second.speed = map.rate_at(clip_t);
    }
    // A graphic's own timeline (road map 10's G-9): the second half starts
    // `clip_t` further into it, and BOTH halves keep the original's length,
    // so the join is invisible and neither half's outro moves — the first
    // half's `in + duration` would otherwise be only the head.
    second.graphic = graphic_advanced(state.graphic.as_ref(), clip_t);
    if let Some(graphic) = second.graphic.as_mut() {
        graphic.length = pinned;
    }
    // Presence of a group is a fact about the clip, so an audio-only clip
    // stays audio-only; only the values come from the evaluation.
    // The cursor's `smoothing` and `hide_idle` stay the original's BASE
    // values, never an end's (spec §11 CU-30).
    second.video = original
        .video
        .as_ref()
        .map(|_| with_base_cursor(state.video.clone(), original.video.as_ref()));
    second.audio = original.audio.map(|_| state.audio);
    second.text = state.text.clone();
    second.shape = original.shape.clone();
    // The transition covers the join with the PREVIOUS clip, which is still
    // the first half's business (spec §6).
    second.transition_in = None;

    // A preset anchored to the clip's two ends, cut in two: the FIRST half
    // keeps the entrance and gives up the exit, the SECOND keeps the exit
    // and gives up the entrance (format version 8). Carrying both to both
    // halves — which is what a bare clone does, and what `text.animation`
    // had done since format version 5 — makes the first half leave at the
    // cut and the second arrive again there, so a join a viewer is not
    // supposed to see becomes the most visible thing in the shot. Neither
    // half's kept slot is rescaled: a preset is a duration, and the tent
    // rule (`motion.rs`) is what handles one now too long for the half it
    // landed on.
    //
    // Both are normalised to the field's "nothing" — `None` for a motion
    // whose slots are all empty, `None` for an animation with no ramp at
    // either end — so a split leaves one spelling of it, `edit_props.rs`'s
    // patch path's rule applied to the other writer that can produce one.
    let motion_of = |video: &mut Option<VideoProps>, keep_in: bool| {
        if let Some(video) = video.as_mut() {
            if let Some(motion) = video.motion.as_mut() {
                if keep_in {
                    motion.out = None;
                } else {
                    motion.r#in = None;
                }
                if motion.is_empty() {
                    video.motion = None;
                }
            }
        }
    };
    motion_of(&mut second.video, false);
    // The second half's word timings (format version 9, spec §11 W-3). A
    // word is anchored to its speech, so the second half keeps ALL of them,
    // rebased by the cut: a negative start means "already said" and the
    // split is invisible. The first half is untouched — its clip time did
    // not move.
    //
    // Except in one case, and only on this half: the text stored here is
    // the EVALUATED text, so a finished action whose end patch switched
    // `content` (which `set_action_end` lets through, where it refuses
    // `words`) lays a new content over the base `words`. A half stored with
    // that mismatch would be a clip the patch door refuses on every later
    // `set_text` or `paste_attributes` — even one that only changes the
    // colour — until the caller sent `words: []`. A half is a clip the door
    // must accept again, so a count that no longer matches stores `[]`: the
    // page draws static, which is what the recipe already drew for it.
    if let Some(text) = second.text.as_mut() {
        if !text.words.is_empty() && token_count(&text.content) != text.words.len() {
            text.words = Vec::new();
        } else {
            rebase_words(text, clip_t);
        }
    }
    if let Some(animation) = second.text.as_mut().and_then(|t| t.animation.as_mut()) {
        animation.r#in = 0;
        if animation.out == 0 {
            if let Some(text) = second.text.as_mut() {
                text.animation = None;
            }
        }
    }

    let mut first_actions: Vec<Action> = Vec::new();
    let mut second_actions: Vec<Action> = Vec::new();
    // The second half's straddled speed action, when its curve re-eases
    // (`ease_in`, `ease_in_out`): the one whose out point can move.
    let mut re_eased: Option<(u32, f64)> = None;
    for action in &original.actions {
        let end = action.start.saturating_add(action.duration);
        if end <= clip_t {
            first_actions.push(action.clone());
        } else if action.start >= clip_t {
            let mut moved = action.clone();
            moved.start = action.start.saturating_sub(clip_t);
            second_actions.push(moved);
        } else {
            // Straddles the cut. The first half ends at the state the
            // evaluation reached there, narrowed to the keys the action
            // animated; the second half keeps the original target. The
            // curve is kept on both halves: re-deriving an exact sub-curve
            // is impossible for the eased forms, and the property values at
            // the endpoints — which is what a viewer sees at the join — are
            // exact either way. A `speed` is not a value seen at the join
            // but integrated to a source position, so the head's end rate
            // is SOLVED to read exactly S(cut) (spec §11 SR-18 (e)); for
            // `ease_out` and `ease_in_out` the rate steps at the cut.
            let mut head = action.clone();
            head.duration = clip_t.saturating_sub(action.start);
            head.end = narrow_to(&patch_source, &action.end, 0);
            let solved = map.as_ref().and_then(|m| m.head_end_rate(action, clip_t));
            if let (Some(rate), Value::Object(end)) = (solved, &mut head.end) {
                end.insert("speed".to_string(), Value::from(rate));
            }
            first_actions.push(head);

            let mut tail = action.clone();
            tail.id = project.allocate_id();
            tail.start = 0;
            tail.duration = end.saturating_sub(clip_t);
            if let (Some(_), Some(rate)) = (&map, end_speed(action)) {
                if matches!(action.curve, Curve::EaseIn | Curve::EaseInOut) {
                    re_eased = Some((tail.id, rate));
                }
            }
            second_actions.push(tail);
        }
    }
    second.actions = second_actions;
    // Only a re-eased tail can read past the file (a `linear` or `ease_out`
    // one reads what the original did, within the constant clip's ±1 tick
    // of rounding): lowered to the largest end rate that fits, or left for
    // the plan's clamp when none does. A splitter never refuses.
    if let Some((tail, rate)) = re_eased {
        if project.overrun(&second).is_some() {
            if let Some(fitting) = project.largest_fitting_end_rate(&second, tail, rate) {
                if let Some(found) = second.actions.iter_mut().find(|a| a.id == tail) {
                    if let Value::Object(end) = &mut found.end {
                        end.insert("speed".to_string(), Value::from(fitting));
                    }
                }
            }
        }
    }

    if let Some(first) = project.clip_mut(clip_id) {
        first.duration = clip_t;
        first.actions = first_actions;
        if let Some(graphic) = first.graphic.as_mut() {
            graphic.length = pinned;
        }
        motion_of(&mut first.video, true);
        if let Some(animation) = first.text.as_mut().and_then(|t| t.animation.as_mut()) {
            animation.out = 0;
            if animation.r#in == 0 {
                if let Some(text) = first.text.as_mut() {
                    text.animation = None;
                }
            }
        }
    }
    project.clips.push(second);
    true
}
    }

    // ---- splitting, deleting, duplicating --------------------------------

    /// Cuts each named clip at project time `at` (spec §6). A clip `at` is
    /// not strictly inside is skipped; when nothing can be cut the whole op
    /// is an identity. `Err` only for an unknown clip id.
    ///
    /// A linked partner is cut too, and the halves are paired (spec §11
    /// AU-92, `edit_link.rs`'s `pair_split_halves`).
    pub fn split_clips(&self, clips: &[u32], at: Ticks) -> Result<Outcome, String> {
        let at = self.snapped(at);
        let ids = self.with_links(clips)?;
        let mut next = self.clone();
        let mut halves: Vec<(u32, u32)> = Vec::new();
        for id in ids {
            // `split_clip` allocates the second half's id first.
            let second = next.next_id;
            if split_clip(&mut next, id, at) {
                halves.push((id, second));
            }
        }
        if halves.is_empty() {
            return Ok(Outcome::Identity);
        }
        pair_split_halves(&mut next, &halves);
        self.finish(next)
    }

    /// Cuts every clip on an UNLOCKED track that `at` falls strictly inside
    /// — ⌘K with no selection (spec §6, §9).
    ///
    /// The SELECTION is all this op computes; the cutting is
    /// [`Project::split_clips`]'s, called rather than copied, so the two
    /// spellings of ⌘K cannot answer differently. An empty selection is its
    /// identity, which is the same answer a list of clips none of which
    /// straddles `at` gets there.
    pub fn split_under_playhead(&self, at: Ticks) -> Result<Outcome, String> {
        let at = self.snapped(at);
        let ids: Vec<u32> = self
            .clips
            .iter()
            .filter(|c| self.track(c.track).is_some_and(|t| !t.locked))
            .filter(|c| c.start < at && at < clip_end(c))
            .map(|c| c.id)
            .collect();
        self.split_clips(&ids, at)
    }

    /// Removes the named clips. Gaps stay — rippling is `edit_time`'s job
    /// (spec §6). A picture takes its linked sound with it; a linked sound
    /// named alone goes alone (spec §11 AU-91, `delete_closure`).
    pub fn delete_clips(&self, clips: &[u32]) -> Result<Outcome, String> {
        let ids = self.delete_closure(clips)?;
        if ids.is_empty() {
            return Ok(Outcome::Identity);
        }
        let mut next = self.clone();
        next.clips.retain(|c| !ids.contains(&c.id));
        self.finish(next)
    }

    /// Copies the named clips immediately after their own span, on their
    /// own tracks (spec §6): the copies start one span-length later, so a
    /// multi-clip selection keeps its internal timing exactly.
    ///
    /// Clips and their actions get fresh ids, and a linked partner is
    /// copied too, the copies linked to each other (spec §11 AU-96).
    /// Refuses when the copies would break the overlap rule.
    pub fn duplicate_clips(&self, clips: &[u32]) -> Result<Outcome, String> {
        let selection: Vec<Clip> = self
            .selected_clips(&self.with_links(clips)?)?
            .into_iter()
            .cloned()
            .collect::<Vec<Clip>>();
        if selection.is_empty() {
            return Ok(Outcome::Identity);
        }
        let span_start = selection.iter().map(|c| c.start).min().unwrap_or(0);
        let span_end = selection.iter().map(clip_end).max().unwrap_or(0);
        let delta = span_end.saturating_sub(span_start);
        if delta <= 0 {
            return Ok(Outcome::Identity);
        }

        let mut next = self.clone();
        let mut copies: Vec<Clip> = Vec::new();
        let mut fresh: HashMap<u32, u32> = HashMap::new();
        for clip in &selection {
            let mut copy = clip.clone();
            next.remint(&mut copy);
            fresh.insert(clip.id, copy.id);
            copy.start = clip.start.saturating_add(delta);
            copies.push(copy);
        }
        relink_copies(&mut copies, &fresh);
        self.commit_additions(next, copies)
    }

    // ---- reversal ---------------------------------------------------------

    /// Plays a media clip back to front, or forward again (spec §6).
    ///
    /// The core does no pixel work, so this only records a FACT about the
    /// clip: neither the plan nor the recipe changes, and Swift resolves it
    /// by substituting a pre-rendered reversed asset for this media's
    /// segments (spec §11).
    ///
    /// The in point is left exactly where it is, and that is the whole
    /// subtlety: `in` is measured in the stream the clip PLAYS
    /// (`model::Source::Media`), so reversing keeps the in point and
    /// therefore shows different frames — the tail of the file instead of
    /// its head. Advancing it to keep the same frames would be a second
    /// convention, and every trim, split and `source_window.rs`'s
    /// `source_length_on_timeline` would need to know which one was in
    /// force.
    ///
    /// A non-media source is an `Err` and not a refusal — the non-media
    /// rule (`edit.rs`, Results). An identity when the clip already plays
    /// that way. Refused on a linked clip (spec §11 AU-94).
    pub fn set_reversed(&self, clip: u32, reversed: bool) -> Result<Outcome, String> {
        let target = self.require_clip(clip)?;
        let Source::Media {
            media,
            r#in,
            reversed: current,
        } = target.source
        else {
            return Err(format!("clip {clip} is not a media clip"));
        };
        if current == reversed {
            return Ok(Outcome::Identity);
        }

        let mut after = target.clone();
        after.source = Source::Media {
            media,
            r#in,
            reversed,
        };
        if let Some(why) = self.linked_rate_refusal(target, &after) {
            return Ok(Outcome::Refused(why));
        }
        let mut next = self.clone();
        if let Some(slot) = next.clip_mut(clip) {
            *slot = after;
        }
        self.finish(next)
    }
}

        }

        let mut moved = target.clone();
        moved.duration = to.saturating_sub(target.start);
        self.commit_replacements(vec![moved])
    }

    /// Drags the clip's end edge to `to_end` by changing its SPEED, not the
    /// source range it shows: `speed = source_len / (to_end - start)`
    /// (spec §6). Media sources only.
    ///
    /// An IDENTITY when the new length is under a frame or the resulting rate
    /// falls outside `SPEED_MIN`–`SPEED_MAX`; refused only when the placement
    /// breaks the overlap rule. Actions keep their clip-relative fraction.
    ///
    /// On a RAMPED clip the whole rate profile scales by f = D ÷ (to_end −
    /// start) through `scaled_profile`, so the ramp keeps its shape and its
    /// window; an f that would take any rate the clip names past the limits
    /// (`profile_factors`) changes nothing (spec §11 SR-19 (a), (b)).
    /// Refused on a linked clip (spec §11 AU-94).
    pub fn rate_stretch(&self, clip: u32, to_end: Ticks) -> Result<Outcome, String> {
        let target = self.require_clip(clip)?.clone();
        if !matches!(target.source, Source::Media { .. }) {
            return Err(format!("clip {clip} is not a media clip"));
        }
        let to_end = self.snapped(to_end);
        let duration = to_end.saturating_sub(target.start);
        if duration < self.frame() {
            return Ok(Outcome::Identity);
        }
        if let Some((low, high)) = profile_factors(&target) {
            let factor = target.duration as f64 / duration as f64;
            if !factor.is_finite() || !(low..=high).contains(&factor) {
                return Ok(Outcome::Identity);
            }
            let moved = self.scaled_profile(&target, factor, duration);
            return self.commit_rate(&target, moved);
        }
        let rate = self.content_length_in_source(&target) as f64 / duration as f64;
        if !rate.is_finite() || !(SPEED_MIN..=SPEED_MAX).contains(&rate) {
            return Ok(Outcome::Identity);
        }

        let mut moved = target.clone();
        moved.speed = rate;
        moved.duration = duration;
        self.rescale_actions(&mut moved.actions, target.duration, duration);
        self.commit_rate(&target, moved)
    }

    /// A rate edit's commit: refused on a linked clip whose rate it changes
    /// (spec §11 AU-94), else placed as any replacement is.
    fn commit_rate(&self, before: &Clip, moved: Clip) -> Result<Outcome, String> {
        if let Some(why) = self.linked_rate_refusal(before, &moved) {
            return Ok(Outcome::Refused(why));
        }
        self.commit_replacements(vec![moved])
    }

    /// Sets the clip's playback rate: `duration = source_len / rate` held
    /// to what the file holds AT THAT RATE (`duration_at_speed`, spec §11
    /// D4-3), actions keeping their clip-relative fraction (spec §6). Media
    /// sources only; `keep_pitch`, when given, sets the time-pitch flag.
    ///
    /// Takes a `rate` or a `duration`, exactly one (spec §11 #190). A
    /// duration is the Fit arm: snapped to the grid, held to a frame, and
    /// turned into the rate that plays the clip's content in it; the current
    /// duration keeps the current rate, so it makes no phantom step.
    ///
    /// Either rate is clamped to `SPEED_MIN`–`SPEED_MAX` rather than
    /// refused, because a slider or an MCP call that asks for more wants the
    /// fastest thing available. `Err` for both or neither, a non-media clip,
    /// a rate that is not a positive finite number or a duration that is not
    /// positive; refuses on an overlap-rule violation.
    ///
    /// On a RAMPED clip the whole rate profile scales by one factor f — the
    /// clamped rate over the base, or D ÷ d — clamped so no rate the clip
    /// names passes a limit (`profile_factors`): the ramp keeps its shape
    /// and its window, and its base may stop short of the rate asked; when
    /// f does not clamp, the base is the clamped rate itself. The
    /// new duration is d, or snapped(round(D ÷ f)) when f clamped or the
    /// rate arm set it, held through `scaled_profile` (spec §11 SR-19 (a),
    /// (b)). An f of 1 changes nothing but `keep_pitch`. A linked clip's
    /// rate is refused (spec §11 AU-94); `keep_pitch` alone is not a rate.
    pub fn set_speed(
        &self,
        clip: u32,
        rate: Option<f64>,
        duration: Option<Ticks>,
        keep_pitch: Option<bool>,
    ) -> Result<Outcome, String> {
        match (rate, duration) {
            (Some(_), Some(_)) => {
                return Err(format!(
                    "set_speed takes a rate or a duration, not both (clip {clip})"
                ))
            }
            (None, None) => {
                return Err(format!(
                    "set_speed takes a rate or a duration (clip {clip})"
                ))
            }
            _ => {}
        }
        let target = self.require_clip(clip)?.clone();
        if !matches!(target.source, Source::Media { .. }) {
            return Err(format!("clip {clip} is not a media clip"));
        }
        if let Some(rate) = rate {
            if !(rate.is_finite() && rate > 0.0) {
                return Err(format!("speed must be a positive number, not {rate}"));
            }
        }
        if let Some(duration) = duration {
            if duration <= 0 {
                return Err(format!("duration must be positive, not {duration}"));
            }
        }
        if let Some((low, high)) = profile_factors(&target) {
            let frame = self.frame();
            let (asked, fitted) = match (rate, duration) {
                (Some(rate), _) => (rate.clamp(SPEED_MIN, SPEED_MAX) / target.speed, None),
                (None, Some(duration)) => {
                    let d = self.snapped(duration).max(frame);
                    if d == target.duration {
                        (1.0, None)
                    } else {
                        (target.duration as f64 / d as f64, Some(d))
                    }
                }
                (None, None) => (1.0, None),
            };
            let factor = asked.clamp(low, high);
            let length = match fitted {
                Some(d) if factor == asked => d,
                _ => {
                    let scaled = (target.duration as f64 / factor).round();
                    if scaled.is_finite() {
                        self.snapped(scaled as Ticks).max(frame)
                    } else {
                        target.duration
                    }
                }
            };
            let mut moved = self.scaled_profile(&target, factor, length);
            // An unclamped rate arm writes the rate asked itself: `speed ×
            // (rate ÷ speed)` can miss it by an ULP (spec §11 SR-19 (a)).
            if let (Some(rate), true) = (rate, factor == asked) {
                moved.speed = rate.clamp(SPEED_MIN, SPEED_MAX);
            }
            if let (Some(keep), Some(audio)) = (keep_pitch, moved.audio.as_mut()) {
                audio.keep_pitch = keep;
            }
            return self.commit_rate(&target, moved);
        }
        let rate = match (rate, duration) {
            (Some(rate), _) => rate,
            (None, Some(duration)) => {
                let d = self.snapped(duration).max(self.frame());
                if d == target.duration {
                    target.speed
                } else {
                    self.content_length_in_source(&target) as f64 / d as f64
                }
            }
            (None, None) => target.speed,
        };
        let rate = rate.clamp(SPEED_MIN, SPEED_MAX);

        let mut moved = target.clone();
        moved.speed = rate;
        moved.duration = self.duration_at_speed(&target, rate);
        self.rescale_actions(&mut moved.actions, target.duration, moved.duration);
        if let (Some(keep), Some(audio)) = (keep_pitch, moved.audio.as_mut()) {
            audio.keep_pitch = keep;
        }
        self.commit_rate(&target, moved)
    }
}
//! `retime_range` — one range of the timeline played faster or slower on
//! every unlocked track, and everything after it moved up or back to stay
//! in step (road map "creator-jobs" CU9a, spec §11 CU-90). One op, so Clip ▸
//! Retime Range… is one undo step, "Retime Range".
//!
//! In order, each a part of CU-90:
//!
//! - (a) `from` and `to` are snapped and clamped to 0, and every time inside
//!   the range maps through `f(t) = snapped(from + round((t − from) ÷
//!   rate))`, `to′ = f(to)`. Both bounds are cut by `split_under_playhead`
//!   (`from`, then `to`), so a straddler splits exactly as `split` splits
//!   it. The PIECES are the clips on unlocked tracks wholly inside the
//!   range, found before the shift; everything at or after `to` moves by
//!   `to′ − to` through `edit_time.rs`'s `shift_clips`, which carries each
//!   moved clip's linked partner (AU-91). A piece starts at `f(s)` and lasts
//!   `f(e) − f(s)`, so pieces that touched still touch: a constant media
//!   piece plays at speed × rate, held to its media by
//!   `duration_resnapped`, its actions keeping their fraction; a ramped one
//!   is `scaled_profile`'s (SR-19); every other kind scales its start and
//!   duration (a graphic keeps its `length`, G-9). Markers inside map
//!   through `f`, markers at or after `to` move with the shift. Inside a
//!   nest the view has no markers and the merge writes none back, so none
//!   moves and none is checked.
//! - (b) Errors, then refusals, in CU-90's order; nothing changes when one
//!   fires. A rate of exactly 1 is an identity once the rate is known to be
//!   in range.
//! - The exit is `finish_placement` over the unlocked tracks.

use crate::edit_clip::clip_end;
use crate::edit_clip_timing::{SPEED_MAX, SPEED_MIN};
use crate::edit_link::linked_rate_sentence;
use crate::edit_speed_profile::profile_factors;
use crate::edit_time::{locked_track, shift_clips, unlocked_tracks};
use crate::model::{Clip, Project, Source};
use crate::outcome::Outcome;
use crate::speed_map::end_speed;
use crate::time::Ticks;

/// The range's time map: `from`, `to` and `to′` on the grid, and `rate`.
struct Retime {
    from: Ticks,
    to: Ticks,
    rate: f64,
    to_new: Ticks,
}

impl Retime {
    /// `f(t)` for a `t` inside `[from, to]`.
    fn map(&self, project: &Project, t: Ticks) -> Ticks {
        let scaled = ((t - self.from) as f64 / self.rate).round();
        project.snapped(self.from.saturating_add(scaled as Ticks))
    }

    /// Where a marker at `t` goes: through `f` inside the range, by the
    /// shift at or after `to`, nowhere before `from`.
    fn marker(&self, project: &Project, t: Ticks) -> Ticks {
        if t >= self.to {
            t.saturating_add(self.to_new - self.to)
        } else if t >= self.from {
            self.map(project, t)
        } else {
            t
        }
    }
}

impl Project {
    /// Plays `[from, to)` at `rate` on every unlocked track and moves what
    /// follows by the range's lost or gained length (spec §6, §11 CU-90).
    /// `keep_pitch`, when given, is set on every media piece's audio, as
    /// `set_speed` sets it.
    pub fn retime_range(
        &self,
        from: Ticks,
        to: Ticks,
        rate: f64,
        keep_pitch: Option<bool>,
    ) -> Result<Outcome, String> {
        if !(rate.is_finite() && rate > 0.0) {
            return Err(format!("rate must be a positive number, not {rate}"));
        }
        let from = self.snapped(from).max(0);
        let to = self.snapped(to).max(0);
        if to <= from {
            return Err(format!(
                "retime_range's to must be after its from (from {from}, to {to} ticks, on the \
                 frame grid)"
            ));
        }
        if !(SPEED_MIN..=SPEED_MAX).contains(&rate) {
            return Ok(Outcome::Refused(format!(
                "a range can be retimed by ×{SPEED_MIN} to ×{SPEED_MAX}, not ×{rate}"
            )));
        }
        if rate == 1.0 {
            return Ok(Outcome::Identity);
        }
        let mut retime = Retime {
            from,
            to,
            rate,
            to_new: to,
        };
        retime.to_new = retime.map(self, to);
        if let Some(why) = self.retime_refusal(&retime) {
            return Ok(Outcome::Refused(why));
        }

        let mut cut = match self.split_under_playhead(from)? {
            Outcome::Applied(split) => split,
            Outcome::Identity | Outcome::Refused(_) => self.clone(),
        };
        if let Outcome::Applied(split) = cut.split_under_playhead(to)? {
            cut = split;
        }
        let unlocked = unlocked_tracks(&cut);
        let pieces: Vec<Clip> = cut
            .clips
            .iter()
            .filter(|c| unlocked.contains(&c.track) && c.start >= from && clip_end(c) <= to)
            .cloned()
            .collect();
        for piece in &pieces {
            if let Some(why) = self.piece_refusal(&cut, piece, &retime) {
                return Ok(Outcome::Refused(why));
            }
        }

        let mut next = cut.clone();
        if let Some(why) = shift_clips(&mut next, to, retime.to_new - to) {
            return Ok(Outcome::Refused(why));
        }
        for piece in &pieces {
            let moved = next.retimed_piece(piece, &retime, keep_pitch);
            if let Some(slot) = next.clip_mut(piece.id) {
                *slot = moved;
            }
        }
        for marker in next.markers.iter_mut() {
            marker.time = retime.marker(self, marker.time);
        }
        let unlocked = unlocked_tracks(&next);
        self.finish_placement(next, &unlocked)
    }

    /// CU-90 (b)'s refusals (2)–(6), on the project as the caller sent it.
    fn retime_refusal(&self, retime: &Retime) -> Option<String> {
        let (from, to) = (retime.from, retime.to);
        if to - from < self.frame().saturating_mul(2) {
            return Some(format!(
                "the range from {from} to {to} ticks is shorter than two frames"
            ));
        }
        for track in self.tracks.iter().filter(|t| t.locked) {
            if self
                .clips
                .iter()
                .any(|c| c.track == track.id && clip_end(c) > from)
            {
                return Some(locked_track(
                    track.id,
                    "its clips after the range's start would fall out of step with the retimed \
                     range",
                ));
            }
        }
        let unlocked = unlocked_tracks(self);
        let inside = self
            .clips
            .iter()
            .filter(|c| unlocked.contains(&c.track) && c.start < to && clip_end(c) > from);
        for clip in inside {
            let c = clip.id;
            if matches!(clip.source, Source::Nest { .. }) {
                return Some(format!(
                    "clip {c} is a nest, which has no speed; move the range off it, or retime \
                     inside the nest"
                ));
            }
            if clip.text.as_ref().is_some_and(|t| !t.words.is_empty()) {
                return Some(format!(
                    "clip {c} is a caption page with timed words, which a retime cannot move; \
                     move the range off it"
                ));
            }
            if let Some(partner) = clip.linked {
                return Some(linked_rate_sentence(c, partner));
            }
        }
        for track in &unlocked {
            for overlap in self.overlaps_on_track(*track) {
                let end = overlap.start.saturating_add(overlap.duration);
                if overlap.start <= to && end >= from {
                    return Some(format!(
                        "clip {} has a transition from clip {} from {} to {end} ticks, which \
                         touches the range; move the range off it or remove the transition",
                        overlap.later, overlap.earlier, overlap.start
                    ));
                }
            }
        }
        let moved: Vec<Ticks> = self
            .markers
            .iter()
            .map(|m| retime.marker(self, m.time))
            .collect();
        for (j, time) in moved.iter().enumerate() {
            if let Some(i) = moved.iter().take(j).position(|t| t == time) {
                return Some(format!(
                    "markers {} and {} would both be at {time} ticks after a retime by ×{}, and \
                     two markers may not share a time; move one of them first",
                    self.markers[i].id, self.markers[j].id, retime.rate
                ));
            }
        }
        None
    }

    /// CU-90 (b)'s refusal (7) for one piece of `cut`: a rate past the
    /// speed limits, or a piece under one frame. The piece is named by its
    /// source clip — a piece `self` has not got is the second half of the
    /// clip that straddled `from` on its track.
    fn piece_refusal(&self, cut: &Project, piece: &Clip, retime: &Retime) -> Option<String> {
        let source = match self.clip(piece.id) {
            Some(clip) => clip.id,
            None => self
                .clips
                .iter()
                .find(|c| {
                    c.track == piece.track && c.start < retime.from && clip_end(c) > retime.from
                })
                .map_or(piece.id, |c| c.id),
        };
        let rate = retime.rate;
        if matches!(piece.source, Source::Media { .. }) {
            let past = match profile_factors(piece) {
                None => Some(piece.speed * rate),
                Some((low, high)) => {
                    let rates = std::iter::once(piece.speed)
                        .chain(piece.actions.iter().filter_map(end_speed));
                    if rate > high {
                        Some(rates.fold(f64::NEG_INFINITY, f64::max) * rate)
                    } else if rate < low {
                        Some(rates.fold(f64::INFINITY, f64::min) * rate)
                    } else {
                        None
                    }
                }
            };
            if let Some(r) = past.filter(|r| !(SPEED_MIN..=SPEED_MAX).contains(r)) {
                let (limit, which) = match r > SPEED_MAX {
                    true => (SPEED_MAX, "fastest"),
                    false => (SPEED_MIN, "slowest"),
                };
                return Some(format!(
                    "clip {source} would play at ×{r}, past ×{limit}, the {which} a clip can play"
                ));
            }
        }
        let length = retime.map(cut, clip_end(piece)) - retime.map(cut, piece.start);
        if length < cut.frame() {
            return Some(format!(
                "clip {source} would last under one frame at ×{rate}"
            ));
        }
        None
    }

    /// One piece retimed: started at `f(s)`, lasting `f(e) − f(s)` — a
    /// media piece at speed × rate (held to its media) or its ramp scaled
    /// (SR-19), every other kind scaled; actions keep their fraction.
    fn retimed_piece(&self, piece: &Clip, retime: &Retime, keep_pitch: Option<bool>) -> Clip {
        let start = retime.map(self, piece.start);
        let length = retime.map(self, clip_end(piece)) - start;
        let mut moved = piece.clone();
        moved.start = start;
        if !matches!(piece.source, Source::Media { .. }) {
            moved.duration = length;
            self.rescale_actions(&mut moved.actions, piece.duration, length);
            return moved;
        }
        if profile_factors(piece).is_some() {
            moved = self.scaled_profile(&moved, retime.rate, length);
        } else {
            moved.speed = piece.speed * retime.rate;
            moved.duration = length;
            moved.duration = self.duration_resnapped(&moved);
            self.rescale_actions(&mut moved.actions, piece.duration, moved.duration);
        }
        if let (Some(keep), Some(audio)) = (keep_pitch, moved.audio.as_mut()) {
            audio.keep_pitch = keep;
        }
        moved
    }
}
/// The most of the span a hold may take. Below 1 so each ramp keeps some
/// length to ease over; one frame is its floor in any case.
pub const HOLD_MAX: f64 = 0.9;

impl RampShape {
    /// The shape as a refusal names it.
    fn name(self) -> &'static str {
        match self {
            RampShape::RampUp => "a ramp up",
            RampShape::RampDown => "a ramp down",
            RampShape::SpeedDip => "a speed dip",
            RampShape::SpeedBurst => "a speed burst",
        }
    }

    /// Whether the target must lie ABOVE the base rate (Up and Burst) or
    /// below it (Down and Dip).
    fn rises(self) -> bool {
        matches!(self, RampShape::RampUp | RampShape::SpeedBurst)
    }

    /// Whether the shape returns to the base rate: two actions and a hold.
    fn returns(self) -> bool {
        matches!(self, RampShape::SpeedDip | RampShape::SpeedBurst)
    }
}

/// One Speed action: a span ending at `rate`.
fn speed_action(id: u32, start: Ticks, duration: Ticks, curve: Curve, rate: f64) -> Action {
    Action {
        id,
        start,
        duration,
        curve,
        end: json!({ "speed": rate }),
    }
}

impl Project {
    /// The speed ramp presets (the module doc, spec §11 SR-23).
    #[allow(clippy::too_many_arguments)]
    pub fn add_speed_ramp(
        &self,
        clip: u32,
        shape: RampShape,
        rate: f64,
        from: Option<Ticks>,
        to: Option<Ticks>,
        curve: Option<Curve>,
        hold: Option<f64>,
    ) -> Result<Outcome, String> {
        let target = self.require_clip(clip)?.clone();
        // Only a media clip has a window to read at a rate; the sentence is
        // the end-rate door's own (`edit_action_speed.rs`).
        read_speed_end(&target, &Value::from(1.0))?;
        if !(rate.is_finite() && rate > 0.0) {
            return Err(format!("rate must be a positive number, not {rate}"));
        }
        let rate = rate.clamp(SPEED_MIN, SPEED_MAX);
        let (from, to) = match (from, to) {
            (None, None) => (0, target.duration),
            (Some(given_from), Some(given_to)) => {
                let from = self.snapped(given_from);
                if from < 0 {
                    return Err(format!("from must not be negative, not {given_from}"));
                }
                (from, self.snapped(given_to))
            }
            _ => return Err("from and to are given together or not at all".to_string()),
        };
        if to <= from {
            return Err(format!("to must be after from, not {to} against {from}"));
        }
        if hold.is_some() && !shape.returns() {
            return Err("hold is for speed_dip and speed_burst only".to_string());
        }

        let length = to - from;
        if to > target.duration {
            return Ok(Outcome::Refused(action_past_end(
                clip,
                from,
                length,
                target.duration,
            )));
        }
        // ONE test over the whole span, whatever the shape (SR-23 (e)).
        if let Some(other) = overlapping_action(&target.actions, None, from, length) {
            return Ok(Outcome::Refused(action_overlaps(clip, other)));
        }
        let frame = self.frame();
        if shape.returns() && length < 2 * frame {
            return Ok(Outcome::Refused(format!(
                "{} needs a span of at least two frames ({} ticks); {from} to {to} ticks is \
                 {length}",
                shape.name(),
                2 * frame
            )));
        }
        let base = rate_in_force(&target, from);
        let wrong_way = if shape.rises() {
            rate <= base
        } else {
            rate >= base
        };
        if wrong_way {
            return Ok(Outcome::Refused(format!(
                "{} needs a rate {} ×{base}, the rate clip {clip} plays at {from} ticks into \
                 it; ×{rate} is not",
                shape.name(),
                if shape.rises() { "above" } else { "below" }
            )));
        }

        let mut next = self.clone();
        let first = next.allocate_id();
        let second = shape.returns().then(|| next.allocate_id());
        let curve = curve.unwrap_or(Curve::EaseInOut);
        // A NaN hold reads as the default; any other is clamped into range.
        let hold = match hold {
            Some(h) if !h.is_nan() => h.clamp(0.0, HOLD_MAX),
            _ => HOLD_DEFAULT,
        };
        let ramp = self
            .snapped_down(((length as f64) * (1.0 - hold) / 2.0) as Ticks)
            .max(frame);
        // The clip with the preset at target rate `x`: the one closure the
        // edit and the fit both build from, so they cannot disagree.
        let build = |x: f64| -> Clip {
            let mut out = target.clone();
            match second {
                None => out
                    .actions
                    .push(speed_action(first, from, length, curve, x)),
                Some(second) => {
                    out.actions.push(speed_action(first, from, ramp, curve, x));
                    out.actions
                        .push(speed_action(second, to - ramp, ramp, curve, base));
                }
            }
            out
        };
        let after = build(rate);
        // A linked clip's rate is refused (spec §11 AU-94).
        if let Some(why) = self.linked_rate_refusal(&target, &after) {
            return Ok(Outcome::Refused(why));
        }
        if let Some(over) = self.overrun(&after) {
            let floor_k = if shape.rises() {
                (base * 1000.0).floor() as i64 + 1
            } else {
                (SPEED_MIN * 1000.0).round() as i64
            };
            let head = format!(
                "{} to ×{rate} would read clip {clip} {over} ticks past the end of its media",
                shape.name()
            );
            return Ok(Outcome::Refused(
                match self.largest_fitting_rate(&build, rate, floor_k) {
                    Some(fit) => format!("{head}; the largest rate that fits is ×{fit}"),
                    None if shape.rises() => format!("{head}, and no rate above ×{base} fits"),
                    None => format!("{head}, and no rate down to ×0.1 fits"),
                },
            ));
        }
        if let Some(slot) = next.clip_mut(clip) {
            *slot = after;
        }
        self.finish(next)
    }
}

        match out.last_mut() {
            Some(last) if span.start <= last.end => last.end = last.end.max(span.end),
            _ => out.push(span),
        }
    }
    out
}

/// THE locked-track refusal, written once (spec §5.5, deepening D2·3).
///
/// Three ops refuse over a lock — `close_gap` and `insert_clip` on their
/// destination track, `add_transition`'s ripple form on the incoming clip's
/// track — and each has its own consequence to report, so `what` is the
/// clause after the comma. What every caller acts on is the same: the id of
/// the track to unlock.
pub(crate) fn locked_track(track: u32, what: &str) -> String {
    format!("track {track} is locked, so {what}")
}

/// The ids of every track a timeline-wide shift may touch.
pub(crate) fn unlocked_tracks(project: &Project) -> Vec<u32> {
    project
        .tracks
        .iter()
        .filter(|t| !t.locked)
        .map(|t| t.id)
        .collect()
}

/// What a shift at `from` moves: every clip on an unlocked track starting
/// at or after `from` (rule 3: a straddler stays), and each one's linked
/// partner on an unlocked track, whatever its start (spec §11 AU-91).
pub(crate) fn shifted(project: &Project, from: Ticks) -> Vec<u32> {
    let unlocked = unlocked_tracks(project);
    let mut out: Vec<u32> = Vec::new();
    for clip in project.clips.iter().filter(|c| c.start >= from) {
        let partner = project.partner(clip.id).map(|p| (p.id, p.track));
        for (id, track) in [Some((clip.id, clip.track)), partner].into_iter().flatten() {
            if unlocked.contains(&clip.track) && unlocked.contains(&track) && !out.contains(&id) {
                out.push(id);
            }
        }
    }
    out
}

/// THE shift primitive: exactly [`shifted`]'s clips move by `delta`, in
/// place. Ripple, the range form and insert time differ only in what they
/// compute for `from` and `delta`. `Some` refusal, nothing moved, when a
/// partner leading its clip would start before 0; the caller answers it as
/// [`Outcome::Refused`] (a ripple closes fully or not at all).
pub(crate) fn shift_clips(project: &mut Project, from: Ticks, delta: Ticks) -> Option<String> {
    if delta == 0 {
        return None;
    }
    let moving = shifted(project, from);
    for id in &moving {
        let Some(clip) = project.clip(*id) else {
            continue;
        };
        if clip.start.saturating_add(delta) < 0 {
            if let Some(partner) = project.partner(*id) {
                return Some(format!(
                    "clip {id} would start before 0: it leads its linked clip {} by {} ticks",
                    partner.id,
                    partner.start.saturating_sub(clip.start)
                ));
            }
        }
    }
    for clip in project.clips.iter_mut() {
        if moving.contains(&clip.id) {
            // Saturating and floored: a caller's delta can never push a
            // clip to a negative start, which `validate` rejects.
            clip.start = clip.start.saturating_add(delta).max(0);
        }
    }
    None
}

/// The bounds a range op works on: snapped, clamped to 0 and put in order,
/// so a drag that ended left of where it began is the same range. `None`
/// for an empty one.
fn ordered_range(project: &Project, from: Ticks, to: Ticks) -> Option<(Ticks, Ticks)> {
    let first = project.snapped(from).max(0);
    let second = project.snapped(to).max(0);
    let (start, end) = if first <= second {
        (first, second)
    } else {
        (second, first)
    };
    (end > start).then_some((start, end))
}

/// Empties `[start, end)` on every unlocked track: both bounds are cut
/// first (`split_under_playhead` IS "split every unlocked clip here"), so
/// afterwards every unlocked clip that touched the range lies entirely
/// inside it, and those are removed.
///
/// Clips on LOCKED tracks are neither split nor removed, even when they lie
/// inside the range: rule 2 is absolute, and a locked track keeps exactly
/// what it had.
///
/// The one thing this does NOT do is decide what happens to the hole, which
/// is the whole difference between a lift and a ripple delete.
fn clear_range(project: &Project, start: Ticks, end: Ticks) -> Result<Project, String> {
    // A splitter has no rule to refuse with — it either cut something or it
    // did not — so both of its non-applied answers mean "nothing was cut at
    // this bound". A splitter that ever gains a rule has to be given a way
    // out of here first: this function answers a `Project`, not an
    // [`Outcome`], so it has nowhere to put a sentence.
    let mut current = match project.split_under_playhead(start)? {
        Outcome::Applied(split) => split,
        Outcome::Identity | Outcome::Refused(_) => project.clone(),
    };
    match current.split_under_playhead(end)? {
        Outcome::Applied(split) => current = split,
        Outcome::Identity | Outcome::Refused(_) => {}
    }

    let unlocked = unlocked_tracks(&current);
    let inside: Vec<u32> = current
        .clips
        .iter()
        .filter(|c| unlocked.contains(&c.track) && c.start >= start && clip_end(c) <= end)
        .map(|c| c.id)
        .collect();
    current.clips.retain(|c| !inside.contains(&c.id));
    Ok(current)
}

// ---- the ops -------------------------------------------------------------

impl Project {
    /// Removes the named clips and closes the holes they leave: for each
    /// removed span, every clip on an UNLOCKED track that starts at or
    /// after the span's end shifts left by the span's length (spec §6).
    ///
    /// The spans are the union of the removed clips' spans and are
    /// processed RIGHT TO LEFT, because shifting for an earlier span moves
    /// the clips a later span's bounds were computed against.
//! Linked pairs — Detach Audio's picture and sound, kept in step (spec §11
//! AU-90…AU-96).
//!
//! A link is a fact two clips state about each other: `Clip.linked` names
//! the partner, the partner names it back, and both sit in one container
//! (the timeline, or one nest). Everything here is a RULE the placement ops
//! ask, not an op of its own but [`Project::attach_audio`]:
//!
//! - **The closure** ([`Project::with_links`]): the clips an op was given,
//!   then each one's partner. `move_clip`, `split`, `duplicate`, `nest` and
//!   `ripple_delete` act on it; `delete` acts on [`Project::delete_closure`],
//!   which lets a SOUND half named alone go alone (AU-91), so Detach Audio
//!   then Delete stays the way to drop a clip's sound. A partner on a locked
//!   track is never added: locks win over links everywhere.
//! - **Settling** ([`Project::settle_links`]): `finish` clears every link
//!   whose partner is gone from the container or does not name it back, so
//!   an op that removes, nests or replaces half a pair writes no code for it
//!   and can never store a one-sided link; [`Project::check_links`] is the
//!   reader's refusal of one.
//! - **Splits and copies** ([`pair_split_halves`], [`relink_copies`]): a cut
//!   pairs the halves (AU-92), and a copy maps its links through the copy's
//!   old → new ids, clearing one whose partner was not copied (AU-96).
//! - **Edges** ([`Project::carried_edge`]): a trim or roll carries to the
//!   partner whose same edge coincides, unless the caller says `alone`
//!   (AU-93) — the J- and L-cut.
//! - **Rates** ([`Project::linked_rate_refusal`]): a linked clip's speed,
//!   direction and speed-naming actions are refused (AU-94), because the
//!   other half would have to be re-timed identically by a second
//!   implementation of every rate op.

use std::collections::HashMap;

use serde_json::Value;

use crate::edit_clip::clip_end;
use crate::model::{Clip, Curve, Project, Source};
use crate::outcome::Outcome;
use crate::speed_map::end_speed;
use crate::time::Ticks;

/// A linked SOUND half: linked, its picture off — the half Detach Audio
/// made, and the half whose edge a J- or L-cut drags alone.
fn is_linked_sound(clip: &Clip) -> bool {
    clip.linked.is_some() && !clip.enabled.video
}

/// AU-94's sentence: `clip`'s rate may not change while it is linked to
/// `partner`. Written once for `linked_rate_refusal` and `retime_range`
/// (spec §11 CU-90 (b)).
pub(crate) fn linked_rate_sentence(clip: u32, partner: u32) -> String {
    format!(
        "clip {clip} is linked to clip {partner}: Attach Audio before changing its speed or \
         direction"
    )
}

/// Every `(clip, named)` in one container whose link is one-sided: the
/// clip it names is absent, is itself, or does not name it back. Read off
/// the container as it stands, so a mutual pair is never on the list and
/// clearing what is cannot break one.
pub(crate) fn relink_copies(clips: &mut [Clip], fresh: &HashMap<u32, u32>) {
    for clip in clips.iter_mut() {
        clip.linked = clip.linked.and_then(|old| fresh.get(&old).copied());
    }
}

impl Project {
    fn unlocked(&self, track: u32) -> bool {
        self.track(track).is_some_and(|t| !t.locked)
    }

    /// The clip `clip` is linked to, when the link is mutual — and so in
    /// the same container, since `Project::clip` searches only this one.
    pub(crate) fn partner(&self, clip: u32) -> Option<&Clip> {
        let named = self.clip(clip)?.linked?;
        if named == clip {
            return None;
        }
        self.clip(named).filter(|c| c.linked == Some(clip))
    }

    /// The named clips in caller order, deduplicated, then each one's
    /// partner on an unlocked track. `Err` on an unknown id, as
    /// `selected_clips` answers.
    pub(crate) fn with_links(&self, clips: &[u32]) -> Result<Vec<u32>, String> {
        self.closure(clips, false)
    }

    /// [`Project::with_links`] for `delete`: a linked SOUND half named
    /// alone adds no partner, so deleting a detached sound keeps its picture
    /// (silent, its link settled away) while deleting a picture takes its
    /// sound (AU-91).
    pub(crate) fn delete_closure(&self, clips: &[u32]) -> Result<Vec<u32>, String> {
        self.closure(clips, true)
    }

    fn closure(&self, clips: &[u32], sound_alone: bool) -> Result<Vec<u32>, String> {
        let named: Vec<&Clip> = self.selected_clips(clips)?;
        let mut out: Vec<u32> = named.iter().map(|c| c.id).collect();
        for clip in named {
            if sound_alone && is_linked_sound(clip) {
                continue;
            }
