            Outcome::Refused(why) => return Ok(Outcome::Refused(why)),
            Outcome::Applied(next) => (next, true),
            Outcome::Identity => (self.clone(), false),
        };
        Ok(match edit(&base, partner)? {
            Outcome::Identity if moved => Outcome::Applied(base),
            other => other,
        })
    }

