226	/// The five groups `paste_attributes` takes by name — `video | audio | text
227	/// | shape | graphic` on the wire. The first four are the PATCH groups
228	/// ([`Group`]); `graphic` is the paste's alone (module doc).
229	#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
230	#[serde(rename_all = "snake_case")]
231	pub enum PasteGroup {
232	    Video,
233	    Audio,
234	    Text,
235	    Shape,
236	    Graphic,
237	}
238	
239	impl PasteGroup {
240	    /// The wire name, which is the patch group's own for the first four.
241	    pub(crate) fn name(self) -> &'static str {
242	        match self.layer() {
243	            Some(layer) => layer.name(),
244	            None => "graphic",
245	        }
246	    }
247	
248	    /// The patch group this names, or `None` for `graphic`, which is not a
249	    /// group of the layer.
250	    fn layer(self) -> Option<Group> {
251	        match self {
252	            PasteGroup::Video => Some(Group::Video),
253	            PasteGroup::Audio => Some(Group::Audio),
254	            PasteGroup::Text => Some(Group::Text),
255	            PasteGroup::Shape => Some(Group::Shape),
256	            PasteGroup::Graphic => None,
257	        }
258	    }
259	
260	    /// The same group as a name a caller could have sent.
261	    fn of(layer: Group) -> PasteGroup {
262	        match layer {
263	            Group::Video => PasteGroup::Video,
264	            Group::Audio => PasteGroup::Audio,
265	            Group::Text => PasteGroup::Text,
266	            Group::Shape => PasteGroup::Shape,
267	        }
268	    }
269	}
