299	/// The copied props as they may be stored: shape-checked with no schema,
300	/// `null`s dropped, counted (G-32 (f)). The sentences are
301	/// `model_graphic.rs`'s own.
302	fn checked_props(from: &GraphicProps) -> Result<Map<String, Value>, String> {
303	    let mut stored = check_props(&from.props, None)?;
304	    stored.retain(|_, value| !value.is_null());
305	    check_count(&stored)?;
306	    Ok(stored)
307	}
