607	impl Project {
608	    /// Collapses `clips` into one nest clip (spec §6).
609	    ///
610	    /// The clips keep their relative times — the earliest starts at 0 inside
611	    /// the nest — their relative track order, their props and their actions;
612	    /// the nest clip covers exactly the span they covered, on the front-most
613	    /// track any of them was on.
614	    ///
615	    /// An empty selection, and a selection of one clip that is already a
616	    /// nest (grouping a group alone changes nothing a user can see), are
617	    /// identities. A nest clip that would break the overlap rule against
618	    /// whatever was NOT selected is refused, in the rule's own sentence. `Err` on an unknown clip id or a selection
619	    /// that would put the project past the track cap.
620	    pub fn nest_clips(&self, clips: &[u32], name: Option<&str>) -> Result<Outcome, String> {
621	        // A linked partner goes in with its clip (spec §11 AU-91).
622	        let selected: Vec<Clip> = self
623	            .selected_clips(&self.with_links(clips)?)?
624	            .into_iter()
625	            .cloned()
626	            .collect::<Vec<_>>();
627	        if selected.is_empty() {
628	            return Ok(Outcome::Identity);
629	        }
630	        if selected.len() == 1 && matches!(selected[0].source, Source::Nest { .. }) {
631	            return Ok(Outcome::Identity);
632	        }
633	        // An adjustment clip grades the top level only (spec §11 GR-6).
634	        if let Some(found) = selected.iter().find(|c| is_adjustment(c)) {
635	            return Ok(Outcome::Refused(adjustment_cannot_nest(found.id)));
636	        }
637	
638	        let earliest = selected.iter().map(|c| c.start).min().unwrap_or(0);
639	        let latest = selected.iter().map(clip_end).max().unwrap_or(0);
640	        if latest <= earliest {
641	            return Ok(Outcome::Identity);
642	        }
643	
644	        // The source tracks, back-most first, so the nest's own stack keeps
645	        // the order the timeline had. `track_index` is the stack position;
646	        // a clip on a track that is not in `tracks` cannot exist (`validate`
647	        // refuses it) and is skipped rather than defended against twice.
648	        let mut sources: Vec<(usize, u32)> = Vec::new();
649	        for clip in &selected {
650	            if let Some(index) = self.track_index(clip.track) {
651	                if !sources.iter().any(|(_, id)| *id == clip.track) {
652	                    sources.push((index, clip.track));
653	                }
654	            }
655	        }
656	        sources.sort_unstable();
657	        // The front-most source track that is not a matte track is where
658	        // the nest clip goes (MT-5): a matte pair nested together must land
659	        // where its picture was drawn, not on the matte track, where the
660	        // whole nest would become a matte. The front-most when all are. The
661	        // nest's own tracks count toward `MAX_TRACKS` like any other
662	        // (`format::check_caps`), so a selection that would overrun the cap
663	        // is caught by `finish` rather than counted twice here.
664	        let drawn = sources
665	            .iter()
666	            .rev()
667	            .find(|(_, id)| self.track(*id).is_some_and(|t| t.matte.is_none()));
668	        let Some((_, front_track)) = drawn.or(sources.last()).copied() else {
669	            return Ok(Outcome::Identity);
670	        };
671	
672	        let mut next = self.clone();
673	        let nest_id = next.allocate_id();
674	        let mut tracks: Vec<Track> = Vec::with_capacity(sources.len());
675	        let mut mapping: Vec<(u32, u32)> = Vec::with_capacity(sources.len());
676	        for (_, id) in &sources {
677	            let Some(source) = self.track(*id) else {
678	                continue;
679	            };
680	            let track = nested_track(&mut next, source, *id != front_track);
681	            mapping.push((*id, track.id));
682	            tracks.push(track);
683	        }
684	        // The carry rule (MT-5), one pass over the mapping: a nested track
685	        // stays a matte only when the nested track directly behind it is the
686	        // copy of its source's target. A matte nested without its target
687	        // draws inside the nest as an ordinary track (owner, O9).
688	        for index in 0..tracks.len() {
689	            let from = mapping.get(index).map(|(from, _)| *from);
690	            let behind = index
691	                .checked_sub(1)
692	                .and_then(|i| mapping.get(i))
693	                .map(|(from, _)| *from);
694	            let carried = from.and_then(|from| matte_target(&self.tracks, from));
695	            if carried.is_none() || carried != behind {
696	                if let Some(track) = tracks.get_mut(index) {
697	                    track.matte = crate::model::TrackMatte::None;
698	                }
699	            }
700	        }
701	
702	        // The clips move WHOLE — ids, actions, transitions and all — so
703	        // nothing about them has to be re-minted or re-checked. Only their
704	        // container changes.
705	        let mut inside: Vec<Clip> = Vec::with_capacity(selected.len());
706	        for clip in &selected {
707	            let Some((_, track)) = mapping.iter().find(|(from, _)| *from == clip.track) else {
708	                continue;
709	            };
710	            let mut moved = clip.clone();
711	            moved.track = *track;
712	            moved.start = clip.start.saturating_sub(earliest);
713	            inside.push(moved);
714	        }
715	        // Any sound inside means the nest clip needs a volume of its own to
716	        // scale it by; a nest of text and shapes gets no audio group, so the
717	        // inspector shows no Audio tab for something that cannot make a
718	        // sound.
719	        let audible = inside.iter().any(|c| c.audio.is_some());
720	
721	        next.clips
722	            .retain(|c| !selected.iter().any(|s| s.id == c.id));
723	        next.nests.push(Nest {
724	            id: nest_id,
725	            name: match name.map(str::trim).filter(|n| !n.is_empty()) {
726	                Some(given) => given.to_string(),
727	                None => format!("Nest {}", next.nests.len().saturating_add(1)),
728	            },
729	            width: next.canvas.width,
730	            height: next.canvas.height,
731	            tracks,
732	            clips: inside,
733	        });
734	
735	        let clip_id = next.allocate_id();
736	        // A transition INTO the selection belonged to a clip that is now
737	        // inside the group, so the nest clip gets the default cross
738	        // dissolve over whatever overlap it inherits — the same rule
739	        // every other op uses for a clip that gains one.
740	        next.clips.push(Clip {
741	            video: Some(VideoProps::default()),
742	            audio: audible.then(AudioProps::default),
743	            ..Clip::placed(
744	                clip_id,
745	                front_track,
746	                earliest,
747	                latest.saturating_sub(earliest),
748	                Source::Nest { project: nest_id },
749	            )
750	        });
751	
752	        if let Err(why) = next.check_overlap_rule(&[], front_track, &[]) {
753	            return Ok(Outcome::Refused(why));
754	        }
755	        self.finish_placement(next, &[front_track])
756	    }
757	
758	    /// Puts a nest clip's contents back on the timeline and removes the clip
759	    /// (spec §6) — the inverse of [`Project::nest_clips`].
760	    ///
761	    /// Each clip returns at `clip.start + its own start`, with fresh ids, on
762	    /// the track counted back from the nest clip's own: the nest's
763	    /// front-most NON-matte track (the front-most when all are, MT-5) lands
764	    /// where the nest clip was, the one behind it a track further back, a
765	    /// carried matte track in front of it a track further forward, and
766	    /// tracks missing behind are added. A clip the overlap rule refuses —
767	    /// or a matte clip with no track in front — goes on a new track in
768	    /// front, ordinary: `unnest` makes no track a matte.
769	    ///
770	    /// The nest itself is dropped when nothing else shows it; a second clip
771	    /// showing it keeps it, which is why the returned clips are copies.
772	    /// `Err` when `clip` is not a nest clip.
773	    pub fn unnest_clip(&self, clip: u32) -> Result<Outcome, String> {
774	        let target = self.require_clip(clip)?.clone();
775	        let Source::Nest { project } = target.source else {
776	            return Err(format!("clip {clip} is not a nest clip"));
777	        };
778	        // `validate` refuses a clip pointing at a nest that is not there, so
779	        // this is a corrupt project rather than a caller's mistake — an
780	        // error either way, naming both ids.
781	        let nest = self
782	            .nest(project)
783	            .ok_or_else(|| format!("clip {clip} shows unknown nest {project}"))?
784	            .clone();
785	
786	        let base = self.require_track_index(target.track)? as i64;
787	        // The nest's front-most non-matte track, the one the nest clip's own
788	        // track stands for (MT-5); the front-most when all are mattes.
789	        let front = nest
790	            .tracks
791	            .iter()
792	            .rposition(|t| t.matte.is_none())
793	            .unwrap_or(nest.tracks.len().saturating_sub(1)) as i64;
794	        let depth = |track: u32| -> i64 {
795	            // 0 for `front`, counting backwards; negative for a carried
796	            // matte track in front of it.
797	            match nest.tracks.iter().position(|t| t.id == track) {
798	                Some(index) => front - index as i64,
799	                None => 0,
800	            }
801	        };
802	        // Bounded by the track cap the project was read under, so the
803	        // deficit loop below can ask for at most `MAX_TRACKS` tracks and
804	        // `finish` refuses the result if that is too many.
805	        let deepest = front;
806	
807	        let mut next = self.clone();
808	        next.clips.retain(|c| c.id != clip);
809	
810	        // Tracks missing behind the destination, exactly as `paste` adds
811	        // them: inserting at index 0 shifts every existing track up, so the
812	        // destination index moves with them.
813	        let base = next.add_tracks_behind(deepest, base);
814	
815	        // Back-most first, then time: the order clips are placed in is the
816	        // order the overlap rule sees them, so it has to be deterministic or
817	        // one nest could open two ways.
818	        let mut ordered: Vec<&Clip> = nest.clips.iter().collect();
819	        ordered.sort_by_key(|c| (std::cmp::Reverse(depth(c.track)), c.start, c.id));
820	
821	        let mut landing = Landing::new(base);
822	        let first = next.clips.len();
823	        let mut fresh: HashMap<u32, u32> = HashMap::new();
824	        for source in ordered {
825	            let mut moved = source.clone();
826	            next.remint(&mut moved);
827	            fresh.insert(source.id, moved.id);
828	            // Translate first; the shared normalization then handles a
829	            // hand-written or legacy off-grid nest on the parent grid.
830	            moved.start = target.start.saturating_add(source.start);
831	            next.resnap_clip_times(&mut moved);
832	            landing.land(&mut next, moved, depth(source.track));
833	        }
834	        // The returning clips re-pair through their fresh ids (AU-96).
835	        if let Some(landed) = next.clips.get_mut(first..) {
836	            relink_copies(landed, &fresh);
837	        }
838	
839	        if !next.nest_is_shown(project) {
840	            next.nests.retain(|n| n.id != project);
841	        }
842	        self.finish_placement(next, landing.touched())
843	    }
844	}
