/// `retime_range` (spec §11 CU-90 (e); road map "creator-jobs" CU9a),
/// mirroring Clip ▸ Retime Range… (`showRetimeSheet` in
/// `EditorViewController+Retime.swift`, whose sheet commits one
/// `retime_range` through `SpeedAudioDrop.commit`): an agent is told in its
/// answer what a person is asked.
extension AgentServer {

    /// Writes its own tail rather than `editResult`'s: the generic answer
    /// diffs the project before and after, where a split half is new and so
    /// never counted, and would overwrite this list with a partial one. The
    /// crossing is read on `SpeedAudioDrop`'s baseline BEFORE the edit, in the
    /// container the call edits.
    func retimeRange(_ a: [String: Any]) throws -> String {
        let document = try target(a)
        let from = try timeArg(a, "from", document)
        let to = try timeArg(a, "to", document)
        guard to > from else {
            throw ToolError(message: "to must be after from (got \(from) and \(to)).")
        }
        guard let rate = try doubleArg(a, "rate") else {
            throw ToolError(message: "Missing required argument: rate (1 = normal speed).")
        }
        guard rate.isFinite && rate > 0 else {
            throw ToolError(message: "rate must be a positive number (1 = normal speed).")
        }
        let keepPitch = try boolArg(a, "keep_pitch")
        let ops: [ReelOp] = [.retimeRange(from: from, to: to, rate: rate, keepPitch: keepPitch)]
        let landing = scopeLanding(ops, document)
        let crossing = SpeedAudioDrop.crossing(
            applying: ops,
            to: effectiveScope(document).flatMap { document.project.scoped($0) }
                ?? document.project)
        let before = try performGroupedEdit(document, "Retime Range", ops)
        var result: [String: Any] = ["ok": true]
        result.merge(Self.created(from: before, to: document.project.snapshot)) { _, new in new }
        result.merge(SpeedAudioDrop.answerFields(crossing)) { _, new in new }
        result.merge(landing) { _, new in new }
        result["project"] = summary(document)
        return try jsonResult(result)
    }
}
    /// `add_speed_ramp` — Clip ▸ Speed Ramp… (`SpeedRampSheetController`,
    /// spec §11 SR-24): a speed ramp preset in one step. `from` and `to` are
    /// CLIP time, like `add_action`'s `at`.
    ///
    /// One op rather than `add_action` + `set_action_end` (SR-25), for
    /// `add_zoom_action`'s reasons: the base rate, the overlap and the rate
    /// that fits are the core's reads (D2-1), and a preset is one undo step.
    /// The undo step is named for the shape, as the sheet names it.
    func addSpeedRamp(_ a: [String: Any]) throws -> String {
        let document = try target(a)
        let clip = try clipArg(a, "clip", document)
        let shape = try requiredEnumArg(a, "shape", SpeedRampShape.self)
        guard let rate = try doubleArg(a, "rate") else {
            throw ToolError(message: "Missing required argument: rate")
        }
        let from = try optionalTimeArg(a, "from", document)
        let to = try optionalTimeArg(a, "to", document)
        let curve = try enumArg(a, "curve", Curve.self)
        let hold = try doubleArg(a, "hold")
        return try addedActionResult(
            document, clip, shape.displayName,
            [
                .addSpeedRamp(
                    clip: clip.id, shape: shape, rate: rate, from: from, to: to, curve: curve,
                    hold: hold)
            ])
    }

    /// The tail every action-adding tool shares: run the ops, then report the
    /// action the clip GAINED. Actions are not top-level ids, so
    /// `created(from:to:)` cannot see them, and the new one is the difference
    /// between the clip's action ids before and after.
    private func addedActionResult(
        _ document: ProjectDocument, _ clip: ClipSnapshot, _ actionName: String,
        _ ops: [ReelOp]
    ) throws -> String {
        let before = clip.actions.map { $0.id }
        // The landing is read BEFORE the edit, like `editResult`'s: how a call
        // was addressed is a fact about the CALL, and reading it back off a
        // view the edit could itself have moved would answer about the wrong
        // thing. It matters here for the same reason it matters there — under
        // phase 9's rule the ABSENCE of `scope` in a result means "this landed
        // on the document", so these two tools (`add_action`, `add_zoom_action`)
        // would otherwise report a nested edit as a document one.
        let landing = scopeLanding(ops, document)
        // The captions `add_speed_ramp` re-times ride in the same step
    /// `get_media_analysis`'s shape, on the server thread: one main hop
    /// resolves the document, the targets and what the store misses; the call
    /// wants that under an owner of its own and waits holding the agent
    /// lane's lock, at most `AnalysisLane.callWaitLimit`; a last main hop
    /// checks the project and scope are still the ones it read, plans and
    /// edits as one undo step. An app-state composite of `split`: no `scope`
    /// key; it acts in the document's current scope.
    func splitAtShots(_ a: [String: Any]) throws -> String {
        let stop = AgentLane.shared.callCancel  // the assistant's Stop (spec §11 AI-16)
        guard !Thread.isMainThread else {
            throw ToolError(
                message: "split_at_shots must run on the server thread — its name is missing "
                    + "from AgentServer.creatorOffMainTools.")
        }
        let (document, targets, skipped, wants, asked, scope) = try onMain {
            let document = try target(a)
            let named = try optionalClipsArg(a, "clips", document)
            let ids = named ?? ShotSplit.unlockedCandidates(in: document.editedProject.snapshot)
            let (targets, skipped) = ShotSplit.targets(ids, in: document.editedProject)
            guard !targets.isEmpty else {
                throw ToolError(
                    message: ShotSplit.Refusal.nothingToSplit(named: named != nil)
                        .localizedDescription)
            }
            let wants: [ShotSplit.Want]
            do {
                wants = try ShotSplit.wants(targets, in: document)
            } catch {
                throw ToolError(message: error.localizedDescription)
            }
            return (document, targets, skipped, wants, document.project, document.scope)
        }
        if !wants.isEmpty {
            try waitForShots(wants, document: document, stop: stop)
        }
        return try onMain {
            guard document.project === asked, document.scope == scope else {
                throw ToolError(
                    message: "the project changed while \(ShotSplit.actionName) was analyzing, "
                        + "so nothing was split. Call split_at_shots again.")
            }
            let plan: ShotSplit.Plan
            do {
                plan = try ShotSplit.plan(targets, in: document)
            } catch {
                throw ToolError(message: error.localizedDescription)
            }
            let fields: [String: Any] = [
                "cuts": plan.cuts.map { ["clip": Int($0.clip), "at": $0.at] as [String: Any] },
                "added": plan.added, "skipped": skipped.map { Int($0) }, "cached": wants.isEmpty,
            ]
            guard !plan.ops.isEmpty else {
                var answer = fields
                answer["ok"] = true
                answer["note"] = "no hard cut lies inside the clips' played windows, so nothing "
                    + "was split"
                answer["project"] = summary(document)
                return try jsonResult(answer)
            }
            return try editResult(document, ShotSplit.actionName, plan.ops, fields)
        }
    }

    /// Wants every request under an owner of the call's own and waits;
    /// throws naming the first media not landed when one failed, the call
    /// was stopped, or the bound passed.
    private func waitForShots(
        _ wants: [ShotSplit.Want], document: ProjectDocument, stop: AgentCallCancel?
    ) throws {
        let lane = AnalysisLane.shared
        let requests = wants.map(\.request)
        let owner = lane.newOwner()
        defer { lane.release(owner: owner) }
        lane.want(
            requests, owner: owner,
            alive: { document.isOpenForAnalysis && !(stop?.isCancelled ?? false) },
            settled: { document.packageContentsDidChangeOnDisk() })
        let outcome = lane.wait(
            for: requests, owner: owner,
            deadline: Date().addingTimeInterval(AnalysisLane.callWaitLimit),
            cancelled: { stop?.isCancelled ?? false })
        let open = wants.first { lane.run(of: $0.request)?.outcome != .landed } ?? wants[0]
        let media = open.media.id
        switch outcome {
        case .landed: return
        case .failed(let why):
            throw ToolError(message: "The shots analysis of media \(media) failed: \(why).")
        case .cancelled:
            throw ToolError(
                message: "The shots analysis of media \(media) was stopped before it finished, "
                    + "so nothing was split.")
        case .timedOut:
            throw ToolError(
                message: "The shots analysis of media \(media) did not finish in the "
                    + "\(Int(AnalysisLane.callWaitLimit)) s a call waits; what it covered is "
                    + "kept — call split_at_shots again to continue.")
        }
    }
}

1	//! `paste` — the clipboard's half of Cut / Copy / Paste (spec §6, table
2	//! "Clips").
3	//!
4	//! Its own module because pasting is a different concern from every other
5	//! placement op: the material does not come from the project. A `move_clip`
6	//! or a `duplicate` rearranges clips the project already owns, so the ids,
7	//! the media and the tracks all exist; a paste arrives as JSON that may have
8	//! been written by ANOTHER document — a different id space, a different
9	//! media list, a different frame grid, possibly a different canvas — and has
10	//! to be made to fit before a single clip lands.
11	//!
12	//! ### The payload
13	//!
14	//! ```json
15	//! {"clips": [ …the §5.2 clip objects… ], "media": [ …the §5.2 media rows… ],
16	//!  "nests": [ …the §5.2 nest objects the clips show… ]}
17	//! ```
18	//!
19	//! It is exactly what `EditorViewController+Clipboard.swift` puts on
20	//! `NSPasteboard.general` under `com.kgalligan.framejob.clips`: the clips
21	//! copied verbatim out of the source document's own `project.json`, plus the
22	//! media rows those clips name and any nest they show. Four things about it
23	//! are worth stating before the code:
24	//!
25	//! 1. **A payload clip's `track` is a DEPTH, not an id** — 0 is the
26	//!    front-most track the copy covered, 1 the one behind it, and so on. A
27	//!    track id from another document means nothing here, and the depth is
28	//!    the only thing about the source's track stack worth carrying: it is
29	//!    what makes a two-lane selection paste back onto two lanes.
30	//! 2. **Ids are re-minted, always.** Clips, actions, any media row the
31	//!    project does not already have, and every nest — with its tracks, its
32	//!    clips and their actions — get fresh ids from `next_id`, so a payload
33	//!    can be pasted repeatedly and into the document it came from.
34	//! 3. **A nest is COPIED, never matched.** Media is matched by path because
35	//!    it names a file two documents can share; a nest is content, and two
36	//!    nests that look alike are no more the same object than two clips are.
37	//!    So every paste of a nest clip brings its own copy, and editing one
38	//!    afterwards leaves the other alone.
39	//! 4. **Unknown keys are ignored**, deliberately: no `deny_unknown_fields`
40	//!    here. The payload is machine-written, a future build will add keys to
41	//!    it, and refusing a whole paste over a key this build has not learned
42	//!    yet would be worse than dropping it — the same reasoning `model.rs`
43	//!    gives for the project schema itself.
44	//!
45	//! ### Making it fit
46	//!
47	//! Every project time is re-snapped to THIS document's frame grid
48	//! ([`Project::snapped`]), because the payload may come from a document at
49	//! another rate; source times are not, for the same reason `trim_start` and
50	//! `split` do not snap them — an `in` point is measured on the media's grid,
51	//! not the canvas's. Media is matched to the existing `media[]` **by path**,
52	//! which is `add_media`'s one-entry-per-path rule, so pasting between two
53	//! documents that both reference `/m/talk.mov` reuses the row that is there
54	//! and pasting into a document that has never seen it brings the row along;
55	//! a row brought along first passes `add_media`'s field checks, with its
56	//! `original` stored as `add_media` stores it, and a row matched by path is
57	//! the project's own and is not checked. Every group of every clip that
58	//! lands, nested ones included, first passes the patch path's
59	//! normalise-and-check, as `paste_attributes`' do — a video group
60	//! `set_video`'s own chain, `Project::settle_video`.
61	    /// is the front-most track, so a paste keeps the copy's own layering.
62	    /// Tracks missing BEHIND the destination are added; a clip the overlap
63	    /// rule refuses on its target track goes on a new track in front.
64	    ///
65	    /// An identity for an empty clip list — the only answer that changes
66	    /// nothing, since the fallback track means a placement cannot fail.
67	    /// `Err` for a malformed payload, an unknown `track`, a clip naming a
68	    /// media the payload does not carry, a depth past the track cap, or a
69	    /// value out of range (`pasted clip N: …`, N the payload's id).
70	    pub fn paste(&self, at: Ticks, track: Option<u32>, payload: &Value) -> Result<Outcome, String> {
71	        let payload = parse_payload(payload)?;
72	        // An explicit destination is an id from THIS project, so an unknown
73	        // one is a caller bug and an error — unlike anything in the payload.
74	        // `tracks.len() - 1` is the front (index 0 is the back, spec §6); a
75	        // project with no tracks at all leaves it at -1, and the deficit
76	        // below adds the one every clip then needs.
77	        let base = match track {
78	            Some(id) => self.require_track_index(id)? as i64,
79	            None => self.tracks.len() as i64 - 1,
80	        };
81	        if payload.clips.is_empty() {
82	            return Ok(Outcome::Identity);
83	        }
84	        let deepest = payload.clips.iter().map(|c| c.track).max().unwrap_or(0) as i64;
85	        // Bounded BEFORE anything is allocated: `track` is a depth here, and
86	        // a payload claiming depth 4 000 000 000 would otherwise ask for four
87	        // billion tracks before `check_caps` ever saw the result.
88	        if deepest >= MAX_TRACKS as i64 {
89	            return Err(format!(
90	                "a pasted clip is {deepest} tracks deep, past the {MAX_TRACKS}-track limit"
91	            ));
92	        }
93	        let at = self.snapped(at).max(0);
94	
95	        let mut next = self.clone();
96	        // The nests first, because their clips name media too: everything
97	        // that will land is resolved against `media[]` in one pass, and the
98	        // nests are then copied in with those ids already mapped.
99	        let nests = reachable_nests(&payload)?;
100	        let landing: Vec<&Clip> = payload
101	            .clips
102	            .iter()
103	            .chain(nests.iter().flat_map(|n| n.clips.iter()))
104	            .collect();
105	        let (sources, looks) = wanted_media(&landing, &payload);
106	        let media = absorb_media(&mut next, &payload, &sources, &looks)?;
107	        let nests = absorb_nests(&mut next, &nests, &media)?;
108	
109	        // Tracks missing behind the destination. Inserting at index 0 shifts
110	        // every existing track up, so the destination index moves with them.
111	        let base = next.add_tracks_behind(deepest, base);
112	
113	        // The earliest clip lands ON `at`, so every other one keeps its own
114	        // distance from it. Offsets are non-negative by construction, which
115	        // is what keeps a paste at 0 from folding clips onto each other.
116	        let earliest = payload.clips.iter().map(|c| c.start).min().unwrap_or(0);
117	
118	        // Back-most depth first, then time: the order clips are placed in is
119	        // the order the overlap rule sees them, so it has to be deterministic
120	        // or the same payload could land two ways.
121	        let mut ordered: Vec<&Clip> = payload.clips.iter().collect();
122	        ordered.sort_by_key(|c| (std::cmp::Reverse(c.track), c.start, c.id));
123	
124	        let mut landing = Landing::new(base);
125	        let first = next.clips.len();
126	        let mut fresh: HashMap<u32, u32> = HashMap::new();
127	        for source in ordered {
128	            let mut clip = source.clone();
129	            next.remint(&mut clip);
130	            fresh.insert(source.id, clip.id);
131	            clip.source = remap_source(&source.source, &media, &nests);
132	            remap_look_media(&mut clip, &media);
133	            remap_hide_silent(&mut clip, &media);
134	            // The payload is trusted about WHAT a clip is and checked about
135	            // what it would do to the project, so a nonsense rate — which
136	            // only a hand-written payload can carry — falls back to 1:1
137	            // rather than reaching the bound below and the composition.
138	            if !(clip.speed.is_finite() && clip.speed > 0.0) {
139	                clip.speed = 1.0;
140	            }
141	            clip.start = at.saturating_add(source.start.saturating_sub(earliest));
142	            // Checked on what the payload sent, before any snap (issue #62).
143	            next.normalise_and_check_pasted(&mut clip, source.id)?;
144	            // `next` and not `self`: the media this clip names was absorbed
145	            // into it above, and only a project that HOLDS the media can
146	            // measure how much window is left (spec §11, D4-4).
147	            next.resnap_clip_times(&mut clip);
148	
149	            // The target track, then the fallbacks already added, then a new
150	            // one.
151	            landing.land(&mut next, clip, source.track as i64);
152	        }
153	        // A payload pair re-pairs through the fresh ids (spec §11 AU-96).
154	        if let Some(landed) = next.clips.get_mut(first..) {
155	            relink_copies(landed, &fresh);
156	        }
157	
158	        self.finish_placement(next, landing.touched())
159	    }
160	}
161	//! `paste_attributes` — Edit ▸ Paste Attributes and Edit ▸ Paste Graphic
162	//! Properties (spec §6, table "Clips"; spec §11 G-32).
163	//!
164	//! Its own module because it is the clipboard's OTHER use: `paste` makes a
165	//! payload fit and places it, and this copies properties onto clips that
166	//! are already there and places nothing. The two share one thing, the
167	//! payload, whose shape stays `edit_paste.rs`'s to know and is read through
168	//! its [`parse_payload`]. Cut out of `edit_paste.rs` under the size rule
169	//! (core/CLAUDE.md), as a pure move, ahead of G-32.
170	//!
171	//! `paste_attributes` copies the EARLIEST payload clip's property groups
172	//! onto clips already on the timeline. It is not in `edit_props.rs` because
173	//! the material comes from the clipboard, not from a caller's patch. A
174	//! group is REPLACED whole, never merged — "make this look like that" is
175	//! the gesture, and a merge would leave the target's shadow under a source
176	//! that had none. What a target keeps is what makes it the clip it is
177	//! rather than how it looks: a text clip's `content` and the `words` that
178	//! time it (spec §11 W-6 — a timing belongs to its words); a shape's
179	//! `kind`, `width`, `height`, `from` and `to`. Video and audio travel whole,
180	//! transform included — `audio.muted` and `keep_pitch` are properties like
181	//! opacity, and `keep_pitch` only acts when the speed is not 1, which does
182	//! not travel: `speed`, `enabled`, the actions, the transition, the name,
183	//! the label and the source are not properties at all.
184	//!
185	//! **The qualifier follows the clip kind** (spec §11 GR-13): only an
186	//! adjustment clip takes one, so a picture target gets none (dropped, which
187	//! `paste_attributes`' description says — D2-1: a paste's answer is not
188	//! the place for it), and an adjustment target keeps its own when the
189	//! payload clip is a picture clip, which has none to give. Between two
190	//! adjustment clips it is copied like any other video key.
191	//!
192	//! ### The fifth group
193	//!
194	//! `graphic` (G-32) copies a graphic clip's `props`, whole, onto clips
195	//! drawn by the SAME module, and the target keeps its `name`, `width`,
196	//! `height`, `in` and `length`. It is a group a caller NAMES and never one
197	//! of the default set: props hold a graphic's words as well as its look,
198	//! and ⌥⌘V has no picker. That is why the names are [`PasteGroup`] and not
199	//! `patch::Group`: a patch has no `graphic` group (G-10), and `Group` is
200	//! matched exhaustively wherever a patch is read.
201	//!
202	//! The copied map is checked for SHAPE only — `model_graphic.rs`'s
203	//! `check_props` with no schema, then `check_count` — and only when a
204	//! target takes it, the first time one does: a paste in which no target
205	//! takes `graphic` never reads the map, as the four groups are checked
206	//! only after they have landed on a target. The write is `insert` and
207	//! `shift_remove`, `model_graphic.rs`'s rule, so a key both sides have
208	//! keeps its slot. A target key the payload lacks that an action on the
209	//! target names (`actions_graphic.rs`'s `names_prop`) is KEPT in its slot,
210	//! so the action's ramp keeps its start (spec §11 G-34 (d), amending
211	//! G-32 (e)).
212	
