271	/// Whether a clip HAS the group — the model's only notion of what a clip
272	/// can take, the same one `edit_props.rs`'s patches go by.
273	fn has_group(clip: &Clip, group: Group) -> bool {
274	    match group {
275	        Group::Video => clip.video.is_some(),
276	        Group::Audio => clip.audio.is_some(),
277	        Group::Text => clip.text.is_some(),
278	        Group::Shape => clip.shape.is_some(),
279	    }
280	}
