282	/// What a graphic clip is drawn from, or `None` for a clip that is not one
283	/// — `set_graphic`'s test: the source AND the description.
284	fn graphic_of(clip: &Clip) -> Option<&GraphicProps> {
285	    match clip.source {
286	        Source::Graphic => clip.graphic.as_ref(),
287	        _ => None,
288	    }
289	}
290	
291	/// Whether a clip has a group a caller can name.
292	fn has(clip: &Clip, group: PasteGroup) -> bool {
293	    match group.layer() {
294	        Some(layer) => has_group(clip, layer),
295	        None => graphic_of(clip).is_some(),
296	    }
297	}
