299	/// The copied props as they may be stored: shape-checked with no schema,
300	/// `null`s dropped, counted (G-32 (f)). The sentences are
301	/// `model_graphic.rs`'s own.
302	fn checked_props(from: &GraphicProps) -> Result<Map<String, Value>, String> {
303	    let mut stored = check_props(&from.props, None)?;
304	    stored.retain(|_, value| !value.is_null());
305	    check_count(&stored)?;
306	    Ok(stored)
307	}
308	
309	/// Makes `into` hold exactly `props` plus the keys in `keep`: a key that
310	/// neither `props` nor `keep` holds is removed with `shift_remove`, a key
311	/// both maps have keeps its slot, a kept key keeps its slot and value, and
312	/// a new key is appended in `props`' order.
313	fn replace_props(into: &mut Map<String, Value>, props: &Map<String, Value>, keep: &[String]) {
314	    let gone: Vec<String> = into
315	        .keys()
316	        .filter(|key| !props.contains_key(*key) && !keep.contains(*key))
317	        .cloned()
318	        .collect();
319	    for key in gone {
320	        into.shift_remove(&key);
321	    }
322	    for (key, value) in props {
323	        into.insert(key.clone(), value.clone());
324	    }
325	}
326	
327	/// Replaces `target`'s group with a copy of `source`'s, keeping the fields
328	/// that make the target the clip it is (module doc). A side that lacks the
329	/// group leaves the target as it was — the caller has already refused that
330	/// case by name, so this is only the shape that cannot invent a group.
331	fn copy_group(target: &mut Clip, source: &Clip, group: Group) {
332	    match group {
333	        Group::Video => {
334	            let picture_target = !is_adjustment(target);
335	            let picture_source = !is_adjustment(source);
336	            if let (Some(into), Some(from)) = (target.video.as_mut(), &source.video) {
337	                let own = into.qualifier;
338	                *into = from.clone();
339	                // The qualifier follows the clip kind (module doc, GR-13).
340	                if picture_target {
341	                    into.qualifier = Qualifier::default();
342	                } else if picture_source {
343	                    into.qualifier = own;
344	                }
345	            }
346	        }
347	        Group::Audio => {
348	            if let (Some(into), Some(from)) = (target.audio.as_mut(), &source.audio) {
349	                *into = *from;
350	            }
351	        }
352	        Group::Text => {
353	            if let (Some(into), Some(from)) = (target.text.as_mut(), &source.text) {
354	                let content = std::mem::take(&mut into.content);
355	                let words = std::mem::take(&mut into.words);
356	                *into = TextProps {
357	                    content,
358	                    words,
359	                    ..from.clone()
360	                };
361	            }
362	        }
363	        Group::Shape => {
364	            if let (Some(into), Some(from)) = (target.shape.as_mut(), &source.shape) {
365	                *into = ShapeProps {
366	                    kind: into.kind,
367	                    width: into.width,
368	                    height: into.height,
369	                    from: into.from,
370	                    to: into.to,
371	                    ..from.clone()
372	                };
373	            }
374	        }
375	    }
376	}
