378	impl Project {
379	    /// Copies one payload clip's property groups onto every named clip (spec
380	    /// §6) — Edit ▸ Paste Attributes. The clip is the EARLIEST, then the
381	    /// front-most (`track` is a depth, 0 = front), then the lower id: Copy
382	    /// writes a selection in storage — creation — order, not the timeline's,
383	    /// so the array's first is a clip the user cannot see. Which fields
384	    /// travel, which a target keeps and why a group is replaced rather than
385	    /// merged are the module doc's.
386	    ///
387	    /// `groups` absent means every one of the four LAYER groups both sides
388	    /// have, silently skipping the rest: video onto a text clip from a media
389	    /// clip copies the video, leaves the text alone and drops the audio,
390	    /// which has nowhere to go. `graphic` is never in that set, and
391	    /// `skip_missing` changes nothing there. A NAMED group is different —
392	    /// one the source lacks is an `Err` naming the group, one a target lacks
393	    /// is `Err("clip N has no audio properties")`, the patches' answer, and
394	    /// `graphic` onto a clip drawn by another module is an `Err` naming both
395	    /// modules — because a caller who asked for it would otherwise never
396	    /// learn it did not happen. With `skip_missing` a caller says it does
397	    /// not need to: a named group the source lacks is dropped and a target
398	    /// that cannot take one is skipped for it (G-32). An empty explicit
399	    /// list, an identity paste and an empty selection are all identities.
400	    /// The copied layer groups then pass the range checks a patch does, so a
401	    /// payload written by hand cannot smuggle in a value the inspector would
402	    /// refuse; copied graphic props pass the shape check, the first time a
403	    /// target takes them.
404	    pub fn paste_attributes(
405	        &self,
406	        clips: &[u32],
407	        payload: &Value,
408	        groups: Option<&[PasteGroup]>,
409	        skip_missing: bool,
410	    ) -> Result<Outcome, String> {
411	        let payload = parse_payload(payload)?;
412	        let earliest = |c: &&Clip| (c.start, c.track, c.id);
413	        let Some(source) = payload.clips.iter().min_by_key(earliest) else {
414	            return Err("paste payload has no clips".to_string());
415	        };
416	        let mut named: Option<Vec<PasteGroup>> = None;
417	        if let Some(asked) = groups {
418	            let mut kept = Vec::new();
419	            for group in asked {
420	                if has(source, *group) {
421	                    kept.push(*group);
422	                } else if !skip_missing {
423	                    return Err(format!("payload clip has no {} properties", group.name()));
424	                }
425	            }
426	            named = Some(kept);
427	        }
428	        let ids: Vec<u32> = self.selected_clips(clips)?.iter().map(|c| c.id).collect();
429	
430	        let mut next = self.clone();
431	        // Read at most once, by the first target that takes it (G-32 (f)).
432	        let mut copied: Option<Map<String, Value>> = None;
433	        // The source with its looks pointing at THIS project's LUTs, made by
434	        // the first target that takes the video group (spec §11 GR-8): the
435	        // LUTs it names are absorbed by path, as `paste` absorbs media, and
436	        // an id the payload lacks becomes no look.
437	        let mut looked: Option<Clip> = None;
438	        for id in ids {
439	            let Some(mut target) = next.clip(id).cloned() else {
440	                continue;
441	            };
442	            let chosen: Vec<PasteGroup> = match &named {
443	                Some(named) => named.clone(),
444	                None => GROUPS
445	                    .into_iter()
446	                    .filter(|g| has_group(source, *g) && has_group(&target, *g))
447	                    .map(PasteGroup::of)
448	                    .collect(),
449	            };
450	            let takes_video = chosen.contains(&PasteGroup::Video) && target.video.is_some();
451	            if takes_video && looked.is_none() {
452	                let looks = [
453	                    look_media_ids(source),
454	                    hide_silent_media(source).into_iter().collect(),
455	                ];
456	                let map = absorb_media(&mut next, &payload, &[], &looks.concat())?;
457	                let mut copy = source.clone();
458	                remap_look_media(&mut copy, &map);
459	                remap_hide_silent(&mut copy, &map);
460	                looked = Some(copy);
461	            }
462	            let from = looked.as_ref().unwrap_or(source);
463	            for group in chosen {
464	                if !has(&target, group) {
465	                    if skip_missing {
466	                        continue;
467	                    }
468	                    return Err(format!("clip {id} has no {} properties", group.name()));
469	                }
470	                let Some(layer) = group.layer() else {
471	                    let keep: Vec<String> = target.graphic.as_ref().map_or_else(Vec::new, |g| {
472	                        let named = g.props.keys().filter(|key| names_prop(&target, key));
473	                        named.cloned().collect()
474	                    });
475	                    let (Some(from), Some(into)) = (graphic_of(from), target.graphic.as_mut())
476	                    else {
477	                        continue;
478	                    };
479	                    if into.name != from.name {
480	                        if skip_missing {
481	                            continue;
482	                        }
483	                        return Err(format!(
484	                            "clip {id} is drawn by \"{}\" and the payload clip by \"{}\"; \
485	                             graphic props are pasted only between clips of one module",
486	                            into.name, from.name
487	                        ));
488	                    }
489	                    if copied.is_none() {
490	                        copied = Some(checked_props(from)?);
491	                    }
492	                    if let Some(props) = &copied {
493	                        replace_props(&mut into.props, props, &keep);
494	                    }
495	                    continue;
496	                };
497	                copy_group(&mut target, from, layer);
498	                next.normalise_and_check_group(&mut target, layer)?;
499	            }
500	            if let Some(slot) = next.clip_mut(id) {
501	                *slot = target;
502	            }
503	        }
504	        self.finish(next)
505	    }
506	}
507	//! `nest` and `unnest` — grouping (spec §6, table "Clips").
508	//!
509	//! The two halves of one idea: a selection of clips becomes ONE clip on the
510	//! timeline showing a [`Nest`], and a nest clip becomes the clips again.
511	//! Their own module because grouping is a different concern from placement
512	//! — no other op changes which CONTAINER a clip lives in — and because the
513	//! pair only makes sense read together.
514	//!
515	//! ### They are inverses, up to ids
516	//!
517	//! `nest` then `unnest` gives back the clips it took: same sources, same
518	//! relative times, same props, same actions, same stacking. The ids differ,
519	//! exactly as they do across `split` then a re-join, because `unnest` mints
520	//! fresh ones — it has to, since a second clip may still show the same nest
521	//! and the clips inside it cannot be in two places at once.
522	//!
523	//! Two asymmetries are deliberate, and both come from the schema:
524	//!
525	//! - **A trimmed nest clip gives everything back.** `Source::Nest` has no in
526	//!   point (spec §5.2), so `unnest` is the inverse of `nest`, not of the
527	//!   trim that followed it: content the nest clip's edges were hiding
528	//!   reappears rather than being destroyed. Nothing is lost, and the user
529	//!   can trim again.
530	//! - **A clip the overlap rule refuses on the way out goes on a new track in
531	//!   front**, the fallback `paste` and Add Text already use (spec §6): a
532	//!   round trip lands on the tracks it came from because the nest clip's own
533	//!   span is free once it is removed, and only a nest that has since been
534	//!   moved next to other material needs the fallback. Refusing the whole op
535	//!   would leave the user with a group they cannot open.
536	//!
537	//! ### What `nest` decides
538	//!
539	//! The nest clip lands on the FRONT-most track the selection occupied that
540	//! is not a matte track (the front-most when all are, spec §11 MT-5), which
541	//! is where the selection's front-most DRAWN layer already was, and runs from
542	//! the earliest start to the latest end. The nest's own canvas is frozen at
543	//! the project's current size, so a later `set_canvas` cannot silently re-lay
544	//! out what is inside it ([`Nest`]). Its tracks are fresh — new ids, the
545	//! source tracks' names and their `hidden`/`muted`/`locked`/`solo` flags —
546	//! because the timeline's tracks stay on the timeline, holding whatever was
547	//! not selected. They copy each source track's `volume` and `pan` too, except
548	//! the copy of the nest clip's own destination track, which is unity and
549	//! centre: that track still applies over the nest clip, so a selection off one
550	//! track sounds the same nested, and the other source tracks' clips now also
551	//! get the destination's volume and pan on top of their own, as they get its
552	//! mute (spec §11 AU-102). `unnest` keeps neither, as it keeps no mute. A nested track keeps its source's `matte` only when the
553	//! nested track directly behind it is the copy of that matte's target (the
554	//! CARRY rule): a matte pair nested together goes on cutting inside the nest,
555	//! and a matte taken without its target becomes an ordinary track there.
556	//!
557	//! `unnest` lines the nest's front-most NON-matte track up with the nest
558	//! clip's track, so carried matte tracks land on the tracks in front of it
559	//! and nest-then-unnest gives the picture back; it makes no track a matte.
560	
561	use std::collections::HashMap;
562	
563	use crate::edit_adjustment::{adjustment_cannot_nest, is_adjustment};
564	use crate::edit_clip::clip_end;
565	use crate::edit_commit::Landing;
566	use crate::edit_link::relink_copies;
567	use crate::model::{AudioProps, Clip, Nest, Project, Source, Track, VideoProps};
568	use crate::outcome::Outcome;
569	use crate::recipe_matte::matte_target;
570	
571	/// A track with a fresh id, copying `from`'s name and its hidden / muted /
572	/// locked / solo / matte state (the matte only provisionally: `nest_clips`
573	/// keeps it by the carry rule alone), and its volume and pan when
574	/// `keeps_mix` (spec §11 AU-102).
575	///
576	/// The state is copied and not cleared: a selection taken off a muted track
577	/// must go on sounding the way it did, and the mute now lives on the nest's
578	/// own track where the user can find it. Solo copies for the same reason —
579	/// what played before nesting plays after — even though a solo is judged
580	/// per container, so inside the nest it is now judged among the nest's own
581	/// tracks.
582	///
583	/// Volume and pan are copied from every source track but the nest clip's
584	/// destination, whose copy gets `keeps_mix` false and so unity and centre:
585	/// the destination track still applies over the nest clip, and a fader
586	/// applied twice is not a fader applied once (where muting twice is muting
587	/// once, so mute copies from it too).
588	///
589	/// A compressor or limiter is never copied (spec §11 AU-150): a nest's own
590	/// tracks have none, and the destination's still apply over the nest clip.
591	fn nested_track(project: &mut Project, from: &Track, keeps_mix: bool) -> Track {
592	    Track {
593	        id: project.allocate_id(),
594	        name: from.name.clone(),
595	        hidden: from.hidden,
596	        muted: from.muted,
597	        locked: from.locked,
598	        solo: from.solo,
599	        matte: from.matte,
600	        volume: if keeps_mix { from.volume } else { 1.0 },
601	        pan: if keeps_mix { from.pan } else { 0.0 },
602	        compressor: None,
603	        limiter: None,
604	    }
605	}
606	
607	impl Project {
608	    /// Collapses `clips` into one nest clip (spec §6).
609	    ///
610	    /// The clips keep their relative times — the earliest starts at 0 inside
611	    /// the nest — their relative track order, their props and their actions;
612	    /// the nest clip covers exactly the span they covered, on the front-most
613	    /// track any of them was on.
614	    ///
615	    /// An empty selection, and a selection of one clip that is already a
616	    /// nest (grouping a group alone changes nothing a user can see), are
617	    /// identities. A nest clip that would break the overlap rule against
618	    /// whatever was NOT selected is refused, in the rule's own sentence. `Err` on an unknown clip id or a selection
619	    /// that would put the project past the track cap.
620	    pub fn nest_clips(&self, clips: &[u32], name: Option<&str>) -> Result<Outcome, String> {
621	        // A linked partner goes in with its clip (spec §11 AU-91).
622	        let selected: Vec<Clip> = self
623	            .selected_clips(&self.with_links(clips)?)?
624	            .into_iter()
625	            .cloned()
626	            .collect::<Vec<_>>();
627	        if selected.is_empty() {
628	            return Ok(Outcome::Identity);
629	        }
630	        if selected.len() == 1 && matches!(selected[0].source, Source::Nest { .. }) {
631	            return Ok(Outcome::Identity);
632	        }
633	        // An adjustment clip grades the top level only (spec §11 GR-6).
634	        if let Some(found) = selected.iter().find(|c| is_adjustment(c)) {
635	            return Ok(Outcome::Refused(adjustment_cannot_nest(found.id)));
636	        }
637	
638	        let earliest = selected.iter().map(|c| c.start).min().unwrap_or(0);
639	        let latest = selected.iter().map(clip_end).max().unwrap_or(0);
640	        if latest <= earliest {
641	            return Ok(Outcome::Identity);
642	        }
643	
644	        // The source tracks, back-most first, so the nest's own stack keeps
645	        // the order the timeline had. `track_index` is the stack position;
646	        // a clip on a track that is not in `tracks` cannot exist (`validate`
647	        // refuses it) and is skipped rather than defended against twice.
648	        let mut sources: Vec<(usize, u32)> = Vec::new();
649	        for clip in &selected {
650	            if let Some(index) = self.track_index(clip.track) {
651	                if !sources.iter().any(|(_, id)| *id == clip.track) {
652	                    sources.push((index, clip.track));
653	                }
654	            }
655	        }
656	        sources.sort_unstable();
657	        // The front-most source track that is not a matte track is where
658	        // the nest clip goes (MT-5): a matte pair nested together must land
659	        // where its picture was drawn, not on the matte track, where the
660	        // whole nest would become a matte. The front-most when all are. The
661	        // nest's own tracks count toward `MAX_TRACKS` like any other
662	        // (`format::check_caps`), so a selection that would overrun the cap
663	        // is caught by `finish` rather than counted twice here.
664	        let drawn = sources
665	            .iter()
666	            .rev()
667	            .find(|(_, id)| self.track(*id).is_some_and(|t| t.matte.is_none()));
668	        let Some((_, front_track)) = drawn.or(sources.last()).copied() else {
669	            return Ok(Outcome::Identity);
670	        };
671	
672	        let mut next = self.clone();
673	        let nest_id = next.allocate_id();
674	        let mut tracks: Vec<Track> = Vec::with_capacity(sources.len());
675	        let mut mapping: Vec<(u32, u32)> = Vec::with_capacity(sources.len());
676	        for (_, id) in &sources {
677	            let Some(source) = self.track(*id) else {
678	                continue;
679	            };
680	            let track = nested_track(&mut next, source, *id != front_track);
681	            mapping.push((*id, track.id));
682	            tracks.push(track);
683	        }
684	        // The carry rule (MT-5), one pass over the mapping: a nested track
685	        // stays a matte only when the nested track directly behind it is the
686	        // copy of its source's target. A matte nested without its target
687	        // draws inside the nest as an ordinary track (owner, O9).
688	        for index in 0..tracks.len() {
689	            let from = mapping.get(index).map(|(from, _)| *from);
690	            let behind = index
691	                .checked_sub(1)
692	                .and_then(|i| mapping.get(i))
693	                .map(|(from, _)| *from);
694	            let carried = from.and_then(|from| matte_target(&self.tracks, from));
695	            if carried.is_none() || carried != behind {
696	                if let Some(track) = tracks.get_mut(index) {
697	                    track.matte = crate::model::TrackMatte::None;
698	                }
699	            }
700	        }
701	
702	        // The clips move WHOLE — ids, actions, transitions and all — so
703	        // nothing about them has to be re-minted or re-checked. Only their
704	        // container changes.
705	        let mut inside: Vec<Clip> = Vec::with_capacity(selected.len());
706	        for clip in &selected {
707	            let Some((_, track)) = mapping.iter().find(|(from, _)| *from == clip.track) else {
708	                continue;
709	            };
710	            let mut moved = clip.clone();
711	            moved.track = *track;
712	            moved.start = clip.start.saturating_sub(earliest);
713	            inside.push(moved);
714	        }
715	        // Any sound inside means the nest clip needs a volume of its own to
716	        // scale it by; a nest of text and shapes gets no audio group, so the
717	        // inspector shows no Audio tab for something that cannot make a
718	        // sound.
719	        let audible = inside.iter().any(|c| c.audio.is_some());
720	
721	        next.clips
722	            .retain(|c| !selected.iter().any(|s| s.id == c.id));
723	        next.nests.push(Nest {
724	            id: nest_id,
725	            name: match name.map(str::trim).filter(|n| !n.is_empty()) {
726	                Some(given) => given.to_string(),
727	                None => format!("Nest {}", next.nests.len().saturating_add(1)),
728	            },
729	            width: next.canvas.width,
730	            height: next.canvas.height,
731	            tracks,
732	            clips: inside,
733	        });
734	
735	        let clip_id = next.allocate_id();
736	        // A transition INTO the selection belonged to a clip that is now
737	        // inside the group, so the nest clip gets the default cross
738	        // dissolve over whatever overlap it inherits — the same rule
739	        // every other op uses for a clip that gains one.
740	        next.clips.push(Clip {
741	            video: Some(VideoProps::default()),
742	            audio: audible.then(AudioProps::default),
743	            ..Clip::placed(
744	                clip_id,
745	                front_track,
746	                earliest,
747	                latest.saturating_sub(earliest),
748	                Source::Nest { project: nest_id },
749	            )
750	        });
751	
752	        if let Err(why) = next.check_overlap_rule(&[], front_track, &[]) {
753	            return Ok(Outcome::Refused(why));
754	        }
755	        self.finish_placement(next, &[front_track])
756	    }
757	
758	    /// Puts a nest clip's contents back on the timeline and removes the clip
759	    /// (spec §6) — the inverse of [`Project::nest_clips`].
760	    ///
761	    /// Each clip returns at `clip.start + its own start`, with fresh ids, on
762	    /// the track counted back from the nest clip's own: the nest's
763	    /// front-most NON-matte track (the front-most when all are, MT-5) lands
764	    /// where the nest clip was, the one behind it a track further back, a
765	    /// carried matte track in front of it a track further forward, and
766	    /// tracks missing behind are added. A clip the overlap rule refuses —
767	    /// or a matte clip with no track in front — goes on a new track in
768	    /// front, ordinary: `unnest` makes no track a matte.
769	    ///
770	    /// The nest itself is dropped when nothing else shows it; a second clip
771	    /// showing it keeps it, which is why the returned clips are copies.
772	    /// `Err` when `clip` is not a nest clip.
773	    pub fn unnest_clip(&self, clip: u32) -> Result<Outcome, String> {
774	        let target = self.require_clip(clip)?.clone();
775	        let Source::Nest { project } = target.source else {
776	            return Err(format!("clip {clip} is not a nest clip"));
777	        };
778	        // `validate` refuses a clip pointing at a nest that is not there, so
779	        // this is a corrupt project rather than a caller's mistake — an
780	        // error either way, naming both ids.
781	        let nest = self
782	            .nest(project)
783	            .ok_or_else(|| format!("clip {clip} shows unknown nest {project}"))?
784	            .clone();
785	
786	        let base = self.require_track_index(target.track)? as i64;
787	        // The nest's front-most non-matte track, the one the nest clip's own
788	        // track stands for (MT-5); the front-most when all are mattes.
789	        let front = nest
790	            .tracks
791	            .iter()
792	            .rposition(|t| t.matte.is_none())
793	            .unwrap_or(nest.tracks.len().saturating_sub(1)) as i64;
794	        let depth = |track: u32| -> i64 {
795	            // 0 for `front`, counting backwards; negative for a carried
796	            // matte track in front of it.
797	            match nest.tracks.iter().position(|t| t.id == track) {
798	                Some(index) => front - index as i64,
799	                None => 0,
800	            }
801	        };
802	        // Bounded by the track cap the project was read under, so the
803	        // deficit loop below can ask for at most `MAX_TRACKS` tracks and
804	        // `finish` refuses the result if that is too many.
805	        let deepest = front;
806	
807	        let mut next = self.clone();
808	        next.clips.retain(|c| c.id != clip);
809	
810	        // Tracks missing behind the destination, exactly as `paste` adds
811	        // them: inserting at index 0 shifts every existing track up, so the
812	        // destination index moves with them.
813	        let base = next.add_tracks_behind(deepest, base);
814	
815	        // Back-most first, then time: the order clips are placed in is the
816	        // order the overlap rule sees them, so it has to be deterministic or
817	        // one nest could open two ways.
818	        let mut ordered: Vec<&Clip> = nest.clips.iter().collect();
819	        ordered.sort_by_key(|c| (std::cmp::Reverse(depth(c.track)), c.start, c.id));
820	
821	        let mut landing = Landing::new(base);
822	        let first = next.clips.len();
823	        let mut fresh: HashMap<u32, u32> = HashMap::new();
824	        for source in ordered {
825	            let mut moved = source.clone();
826	            next.remint(&mut moved);
827	            fresh.insert(source.id, moved.id);
828	            // Translate first; the shared normalization then handles a
829	            // hand-written or legacy off-grid nest on the parent grid.
830	            moved.start = target.start.saturating_add(source.start);
831	            next.resnap_clip_times(&mut moved);
832	            landing.land(&mut next, moved, depth(source.track));
833	        }
834	        // The returning clips re-pair through their fresh ids (AU-96).
835	        if let Some(landed) = next.clips.get_mut(first..) {
836	            relink_copies(landed, &fresh);
837	        }
838	
839	        if !next.nest_is_shown(project) {
840	            next.nests.retain(|n| n.id != project);
841	        }
842	        self.finish_placement(next, landing.touched())
843	    }
844	}
