enum ShotSplit {
    static let actionName = "Split at Shot Changes"

    struct Target {
        let clip: ClipSnapshot
        let media: MediaSnapshot
        let times: AnalysisClipTimes
    }

    struct Want {
        let media: MediaSnapshot
        let request: AnalysisRequest
    }

    struct Plan {
        let ops: [ReelOp]
        let cuts: [(clip: UInt32, at: [Ticks])]
        let added: Int
    }

