186	/// Resolves every media the pasted clips name onto an entry of this
187	/// project's `media[]`, appending the ones that are not there, and returns
188	/// the payload-id → project-id map.
189	///
190	/// `sources` are the media the landing clips SHOW and `looks` the LUTs their
191	/// looks name ([`wanted_media`]) — the payload's own clips AND those inside
192	/// the nests they show, which reference the payload's `media[]` in the same
193	/// one id space (spec §5.2) and would otherwise dangle.
194	///
195	/// Only media a pasted clip actually shows or looks through is brought
196	/// across. The pasteboard writer only ever puts those there, and a payload
197	/// row nothing references would arrive as a Media-tab entry the user did not
198	/// ask for and cannot account for.
199	///
200	/// `Err` when a clip shows a media the payload does not carry (a truncated
201	/// or hand-written payload — the clip would otherwise become a dangling
202	/// reference `validate` refuses), when a row's path is empty, or when a row
203	/// about to be APPENDED fails `add_media`'s field checks
204	/// (`edit_track.rs`'s `check_media_fields`, on the row with its `original`
205	/// stored as `add_media` stores it; `pasted media N: …`, N the payload's
206	/// id). A row matched by path is the project's own and is not checked. A
207	/// look's id the payload lacks is skipped (spec §11 GR-8).
208	///
209	/// A row APPENDED here keeps its Camera Log (spec §11 GR-16) with its
210	/// `color.lut` pointed at this project's id for that LUT, or loses its
211	/// `color` when the LUT did not come with it; a row matched by path keeps
212	/// its own.
213	pub(crate) fn absorb_media(
214	    project: &mut Project,
215	    payload: &Payload,
216	    sources: &[u32],
217	    looks: &[u32],
218	) -> Result<HashMap<u32, u32>, String> {
219	    let mut map: HashMap<u32, u32> = HashMap::new();
220	    let mut appended: Vec<u32> = Vec::new();
221	    for (id, shown) in sources
222	        .iter()
223	        .map(|id| (*id, true))
224	        .chain(looks.iter().map(|id| (*id, false)))
225	    {
226	        if map.contains_key(&id) {
227	            continue;
228	        }
229	        let Some(entry) = payload.media.iter().find(|m| m.id == id) else {
230	            if shown {
231	                return Err(format!(
232	                    "a pasted clip shows media {id}, which the payload does not carry"
233	                ));
234	            }
235	            // A look's LUT the payload lacks (an end may name one that is
236	            // gone, spec §11 GR-8): left out of the map, so
237	            // `remap_look_media` makes it no look.
238	            continue;
239	        };
240	        let path = entry.path.trim().to_string();
241	        if path.is_empty() {
242	            return Err("a pasted media path must not be empty".to_string());
243	        }
244	        let local = match project.media.iter().find(|m| m.path == path) {
245	            Some(found) => found.id,
246	            None => {
247	                let mut record = entry.clone();
248	                record.path = path;
249	                // An empty bookmark is not a bookmark — `add_media`'s rule.
250	                record.bookmark = record.bookmark.filter(|b| !b.trim().is_empty());
251	                // `add_media`'s own field checks, on the row as it would be
252	                // stored (issue #349), before it takes an id.
253	                record.original = normalize_original(record.original);
254	                check_media_fields(&record).map_err(|why| format!("pasted media {id}: {why}"))?;
255	                record.id = project.allocate_id();
256	                let new_id = record.id;
257	                project.media.push(record);
258	                appended.push(new_id);
259	                new_id
260	            }
261	        };
262	        map.insert(id, local);
263	    }
264	    for row in project.media.iter_mut() {
265	        if !appended.contains(&row.id) {
266	            continue;
267	        }
268	        if let Some(lut) = row.color.and_then(|color| color.lut) {
269	            match map.get(&lut) {
270	                Some(local) => {
271	                    if let Some(color) = row.color.as_mut() {
272	                        color.lut = Some(*local);
273	                    }
274	                }
275	                None => row.color = row.color.and_then(|color| color.without_camera_log()),
276	            }
277	        }
278	    }
279	    Ok(map)
280	}
