282	/// The ids `absorb_media` resolves for `clips`, in the order they name
283	/// them (a `Vec` rather than a set, so the new rows are appended and
284	/// numbered reproducibly): the media each SHOWS, then the LUTs their looks
285	/// name (spec §11 GR-8) and the LUT each shown media's payload row converts
286	/// with (`color.lut`, GR-16).
287	fn wanted_media(clips: &[&Clip], payload: &Payload) -> (Vec<u32>, Vec<u32>) {
288	    let mut sources: Vec<u32> = Vec::new();
289	    let mut looks: Vec<u32> = Vec::new();
290	    for clip in clips {
291	        if let Some(id) = clip.source.media() {
292	            if !sources.contains(&id) {
293	                sources.push(id);
294	            }
295	        }
296	        for id in look_media_ids(clip)
297	            .into_iter()
298	            .chain(hide_silent_media(clip))
299	        {
300	            if !looks.contains(&id) {
301	                looks.push(id);
302	            }
303	        }
304	    }
305	    let converting = sources.iter().filter_map(|id| {
306	        let row = payload.media.iter().find(|m| m.id == *id)?;
307	        row.color?.lut
308	    });
309	    for id in converting.collect::<Vec<u32>>() {
310	        if !looks.contains(&id) {
311	            looks.push(id);
312	        }
313	    }
314	    (sources, looks)
315	}
