317	/// Parses the payload, naming what was wrong.
318	pub(crate) fn parse_payload(payload: &Value) -> Result<Payload, String> {
319	    if !payload.is_object() {
320	        return Err(format!(
321	            "a paste payload must be a json object, not {}",
322	            describe(payload)
323	        ));
324	    }
325	    serde_json::from_value(payload.clone())
326	        .map_err(|e| format!("paste payload does not match the schema: {e}"))
327	}
