120	/// Copies every reachable payload nest into the project with fresh ids
121	/// throughout — the nest, its tracks, its clips and their actions — and
122	/// returns the payload-id → project-id map.
123	///
124	/// Every nest gets its new id BEFORE any is rewritten, so a nest showing
125	/// another nest is remapped whichever order the two were discovered in.
126	/// Times inside are re-snapped to this document's frame grid for the same
127	/// reason the pasted clips' are: the payload may come from a document at
128	/// another rate, and nothing sub-frame may reach the model.
129	///
130	/// `Err` when a clip inside fails [`Project::normalise_and_check_pasted`].
131	/// That runs in a second pass, once every copy is in, so a clip showing a
132	/// nest is measured against the copy it shows.
133	fn absorb_nests(
134	    project: &mut Project,
135	    nests: &[&Nest],
136	    media: &HashMap<u32, u32>,
137	) -> Result<HashMap<u32, u32>, String> {
138	    let mut map: HashMap<u32, u32> = HashMap::new();
139	    for nest in nests {
140	        map.insert(nest.id, project.allocate_id());
141	    }
142	    let first = project.nests.len();
143	    for nest in nests {
144	        let mut copy = (*nest).clone();
145	        copy.id = map.get(&nest.id).copied().unwrap_or(nest.id);
146	        let mut tracks: HashMap<u32, u32> = HashMap::new();
147	        for track in copy.tracks.iter_mut() {
148	            let id = project.allocate_id();
149	            tracks.insert(track.id, id);
150	            track.id = id;
151	        }
152	        let mut fresh: HashMap<u32, u32> = HashMap::new();
153	        for clip in copy.clips.iter_mut() {
154	            let old = clip.id;
155	            project.remint(clip);
156	            fresh.insert(old, clip.id);
157	            clip.track = tracks.get(&clip.track).copied().unwrap_or(clip.track);
158	            clip.source = remap_source(&clip.source, media, &map);
159	            remap_look_media(clip, media);
160	            remap_hide_silent(clip, media);
161	            // The speed BEFORE the duration: the bound is measured at it.
162	            if !(clip.speed.is_finite() && clip.speed > 0.0) {
163	                clip.speed = 1.0;
164	            }
165	        }
166	        // A copied pair re-pairs through the fresh ids (spec §11 AU-96).
167	        relink_copies(&mut copy.clips, &fresh);
168	        project.nests.push(copy);
169	    }
170	    for (offset, nest) in nests.iter().enumerate() {
171	        let index = first + offset;
172	        let Some(mut clips) = project.nests.get(index).map(|n| n.clips.clone()) else {
173	            continue;
174	        };
175	        for (clip, source) in clips.iter_mut().zip(&nest.clips) {
176	            project.normalise_and_check_pasted(clip, source.id)?;
177	            project.resnap_clip_times(clip);
178	        }
179	        if let Some(copy) = project.nests.get_mut(index) {
180	            copy.clips = clips;
181	        }
182	    }
183	    Ok(map)
184	}
